import {createStudentPortal} from './student.js';
import {LECTURE_MULTI} from './lecture-multi.js';
import {SECURITY_PLUS,pickSecurityQuestions} from './security-plus.js';
import {createClient} from '@supabase/supabase-js';
import {normalizeProgress,safeAnswers} from './state.js';
