const LESSONS = [{"id": "w1-start", "track": 1, "title": "Od czego zaczynamy?", "subtitle": "Jak działa kurs i co będziemy chronić", "slides": "Wykład 1 · slajdy 12–23", "icon": "🎒", "sections": [{"title": "Co to jest bezpieczeństwo IT?", "paragraphs": ["IT (Information Technology) to technologie informacyjne: komputery, sieci, serwery, programy i dane. <strong>Bezpieczeństwo IT<\/strong> ma chronić informacje oraz systemy przed nieuprawnionym dostępem, zmianą, utratą i niedostępnością.", "Przykład z życia: masz w telefonie prywatne zdjęcia, aplikację bankową i hasła. Chcesz, żeby obca osoba nie mogła ich odczytać, zmienić ani zablokować Ci dostępu."], "bullets": []}, {"title": "Czym są zasób, zagrożenie i podatność?", "paragraphs": ["<strong>Zasób (asset)<\/strong> to coś wartościowego, np. plik, konto, serwer lub baza danych. <strong>Zagrożenie (threat)<\/strong> to coś, co może wyrządzić szkodę, np. przestępca albo awaria. <strong>Podatność (vulnerability)<\/strong> to słabość, którą zagrożenie może wykorzystać: łatwe hasło lub niezałatany program.", "Wyobraź sobie dom: laptop to zasób, złodziej to zagrożenie, otwarte okno to podatność, a zamek i alarm to zabezpieczenia. <strong>Ryzyko<\/strong> wiąże się z prawdopodobieństwem szkody i jej skutkami."], "bullets": []}, {"title": "Jak wygląda zaliczenie według slajdów?", "paragraphs": ["Wykładowca zaplanował 15 spotkań i zejściówki w Wayground. Pierwsza jest testowa i nie daje punktów; pozostałe 14 × 10 pytań daje maksymalnie <strong>140 punktów<\/strong>. Zaliczenie zaczyna się od <strong>71 punktów<\/strong>, a 5,0 od <strong>126 punktów<\/strong>.", "Prezentacja mówi, że zdany CompTIA Security+ przed końcem zajęć pozwala uzyskać 5,0 bez zejściówek. To <strong>zasady przedstawione w materiale wykładowcy<\/strong>, nie uniwersalny regulamin każdej uczelni."], "bullets": []}], "remember": "Zasób = co chronimy; zagrożenie = co może zaszkodzić; podatność = słabość; zabezpieczenie = co zmniejsza ryzyko.", "example": "Przykład: konto uczelniane jest zasobem, phishing zagrożeniem, używanie jednego hasła w wielu serwisach podatnością, a MFA zabezpieczeniem.", "pitfalls": "Nie myl zagrożenia z podatnością. Złodziej nie jest podatnością — podatnością są np. otwarte drzwi.", "quiz": [{"q": "Co jest podatnością?", "options": ["Haker próbujący włamania", "Nieaktualne oprogramowanie z luką", "Baza danych klientów"], "answer": 1, "why": "Podatność to słabość systemu. Haker to zagrożenie, a baza klientów to zasób."}, {"q": "Ile punktów trzeba zdobyć na zaliczenie według wykładu?", "options": ["51", "71", "140"], "answer": 1, "why": "Ze 140 dostępnych punktów próg zaliczenia to 71."}], "visual": null}, {"id": "w1-cia", "track": 1, "title": "Triada CIA", "subtitle": "Trzy filary: poufność, integralność i dostępność", "slides": "Wykład 1 · slajdy 25–29", "icon": "🔺", "sections": [{"title": "C — Confidentiality, czyli poufność", "paragraphs": ["<strong>Poufność<\/strong> oznacza, że informację mogą odczytać tylko osoby do tego uprawnione. Wyobraź sobie pamiętnik zamknięty na kłódkę: treść nie powinna trafić w obce ręce.", "W IT służą temu np. szyfrowanie, hasła i kontrola dostępu. Dane medyczne, wynagrodzenia, prywatne wiadomości i tajemnice firmy wymagają poufności."], "bullets": []}, {"title": "I — Integrity, czyli integralność", "paragraphs": ["<strong>Integralność<\/strong> oznacza ochronę danych przed nieuprawnionymi zmianami i możliwość wykrycia naruszenia. Wysłałaś przelew 50 zł, ale ktoś zmienił kwotę na 5000 zł — to problem integralności.", "Plomba na opakowaniu pomaga wykryć otwarcie. W IT podobną funkcję mogą pełnić skróty kryptograficzne (hash), podpisy cyfrowe i inne mechanizmy. Ważne: integralność nie oznacza, że nigdy nie wolno nic zmieniać — zmiany mogą być autoryzowane."], "bullets": []}, {"title": "A — Availability, czyli dostępność", "paragraphs": ["<strong>Dostępność<\/strong> oznacza, że uprawniona osoba może używać danych i systemu, kiedy ich potrzebuje. Gdy strona banku nie działa, nie możesz zrobić przelewu, nawet jeśli nikt nie ukradł danych.", "Pomagają w tym kopie zapasowe (backup), nadmiarowość (redundancy), zapasowe serwery, łącza i zasilanie."], "bullets": []}, {"title": "Czy jeden incydent narusza tylko jedną cechę?", "paragraphs": ["Nie. Ransomware może zablokować dostęp do plików (dostępność), a jeśli napastnik dodatkowo wykradnie dane — naruszy też poufność. Jedno zabezpieczenie także może chronić kilka elementów CIA."], "bullets": []}], "remember": "C = kto może przeczytać? I = czy dane są poprawne i niezmienione bez zgody? A = czy mogę ich użyć w potrzebnym momencie?", "example": "System ocen: inny student widzi Twoją ocenę → C; ktoś zmienia 5 na 2 → I; platforma nie działa → A.", "pitfalls": "Samo szyfrowanie nie gwarantuje zawsze integralności ani dostępności; efekt zależy od konkretnego zastosowania.", "quiz": [{"q": "Ktoś zmienił bez zgody numer konta na fakturze. Co naruszono?", "options": ["Poufność", "Integralność", "Dostępność"], "answer": 1, "why": "Nieuprawniona zmiana wartości to naruszenie integralności."}, {"q": "Serwer uczelni nie działa podczas zapisów. Co ucierpiało?", "options": ["Dostępność", "Poufność", "Uwierzytelnianie"], "answer": 0, "why": "Uprawnieni studenci nie mogą korzystać z usługi — chodzi o dostępność."}], "visual": "cia"}, {"id": "w1-nist", "track": 1, "title": "NIST CSF krok po kroku", "subtitle": "Co robić przed atakiem, podczas i po", "slides": "Wykład 1 · slajdy 30–32", "icon": "🗺️", "sections": [{"title": "Dlaczego potrzebny jest framework?", "paragraphs": ["Firma nie chroni jednego pliku: ma mnóstwo komputerów, pracowników, procesów i danych. Potrzebuje planu, żeby wiedzieć, co robić w pierwszej kolejności. <strong>Framework<\/strong> to ramy postępowania, a nie pojedynczy program.", "<strong>NIST<\/strong> to National Institute of Standards and Technology. Jego Cybersecurity Framework (CSF) porządkuje działania bezpieczeństwa."], "bullets": []}, {"title": "Pięć klasycznych funkcji", "paragraphs": ["Wyobraź sobie ochronę hotelu. <strong>Identify<\/strong>: spisz wartościowe zasoby i zagrożenia. <strong>Protect<\/strong>: ustaw zamki, hasła i zasady. <strong>Detect<\/strong>: obserwuj alarmy. <strong>Respond<\/strong>: reaguj na włamanie. <strong>Recover<\/strong>: przywróć usługi do działania.", "Te funkcje tworzą ciągły proces: po incydencie uczysz się na błędach i znów oceniasz ryzyko."], "bullets": []}, {"title": "A gdzie szósta funkcja?", "paragraphs": ["Slajd wskazuje, że w <strong>NIST CSF 2.0 (2024)<\/strong> dodano <strong>Govern (Zarządzaj)<\/strong>: ustalanie odpowiedzialności, zasad i nadzoru nad pozostałymi funkcjami. Na kursie omawiana jest też klasyczna piątka funkcji."], "bullets": []}], "remember": "Identyfikuj → Chroń → Wykrywaj → Reaguj → Odtwarzaj. W wersji 2.0 dodatkowo Zarządzaj (Govern).", "example": "Firma: lista serwerów → MFA → wykrycie logowania z obcego kraju → blokada konta → przywrócenie bezpiecznego dostępu.", "pitfalls": "NIST CSF nie jest pojedynczym antywirusem ani listą ustawień do skopiowania: mówi, jakie obszary działań należy uwzględnić.", "quiz": [{"q": "Która funkcja NIST polega na zauważeniu ataku?", "options": ["Protect", "Detect", "Recover"], "answer": 1, "why": "Detect znaczy wykrywaj — monitoruj zdarzenia, aby zauważyć incydent."}, {"q": "Co dodano jako szóstą funkcję w CSF 2.0?", "options": ["Govern", "Encrypt", "Attack"], "answer": 0, "why": "Govern oznacza zarządzanie i nadzór."}], "visual": "nist"}, {"id": "w1-access", "track": 1, "title": "Kontrola dostępu i AAA", "subtitle": "Kto jesteś, czy to Ty, co wolno i kto co zrobił", "slides": "Wykład 1 · slajd 33", "icon": "🎫", "sections": [{"title": "Kontrola dostępu — Access Control", "paragraphs": ["Kontrola dostępu polega na ustalaniu, <strong>kto<\/strong> ma dostęp do <strong>czego<\/strong> i z <strong>jakimi uprawnieniami<\/strong>. W hotelu karta gościa otwiera jego pokój, ale nie pomieszczenie z kasą."], "bullets": []}, {"title": "1. Identification — identyfikacja", "paragraphs": ["Podajesz login. System dowiaduje się, o które konto chodzi. Sam login nie jest jeszcze dowodem, że naprawdę jesteś właścicielką konta."], "bullets": []}, {"title": "2. Authentication — uwierzytelnianie", "paragraphs": ["Udowadniasz tożsamość: hasłem, odciskiem palca albo kluczem sprzętowym. <strong>MFA<\/strong> oznacza połączenie różnych rodzajów czynników, np. hasła oraz potwierdzenia na telefonie. Dwa różne hasła nie są dwoma różnymi czynnikami MFA."], "bullets": []}, {"title": "3. Authorization — autoryzacja", "paragraphs": ["System sprawdza, co możesz zrobić. Student może odczytać swoje oceny, ale nie zmieniać ich. <strong>Least Privilege<\/strong> to zasada najmniejszych uprawnień: dostajesz wyłącznie to, czego potrzebujesz."], "bullets": []}, {"title": "4. Accounting — rozliczalność", "paragraphs": ["System tworzy <strong>logi<\/strong>, czyli dzienniki zdarzeń: kto się logował, kiedy i co zrobił. To pozwala później badać incydenty. Kroki 2–4 tworzą skrót <strong>AAA<\/strong>."], "bullets": []}], "remember": "Identyfikacja: „Jestem Ania”. Uwierzytelnienie: „Udowodnij”. Autoryzacja: „Co wolno?”. Rozliczalność: „Co zrobiłaś?”.", "example": "Hotel: nazwisko rezerwacji → dokument → karta do pokoju 204 → zapis użycia karty.", "pitfalls": "Nie myl uwierzytelniania z autoryzacją: poprawne hasło nie oznacza dostępu do wszystkich plików.", "quiz": [{"q": "System sprawdza, czy student może zmienić ocenę. To…", "options": ["identyfikacja", "autoryzacja", "backup"], "answer": 1, "why": "Autoryzacja sprawdza prawa i uprawnienia."}, {"q": "Co oznacza A-A-A?", "options": ["Authentication, Authorization, Accounting", "Access, Algorithm, Antivirus", "Audit, Asset, Availability"], "answer": 0, "why": "Skrót AAA oznacza uwierzytelnianie, autoryzację, rozliczalność."}], "visual": "aaa"}, {"id": "w1-categories", "track": 1, "title": "4 kategorie zabezpieczeń", "subtitle": "Zarządcze, operacyjne, techniczne, fizyczne", "slides": "Wykład 1 · slajdy 34–37", "icon": "🧱", "sections": [{"title": "Co nazywamy kontrolą bezpieczeństwa?", "paragraphs": ["<strong>Security control<\/strong> to środek chroniący zasoby. Może to być dokument, działanie człowieka, ustawienie programu albo rzeczywista bariera. Na wykładzie kategorie odpowiadają na pytanie <strong>kto lub co działa?<\/strong>"], "bullets": []}, {"title": "Managerial — zarządcze", "paragraphs": ["Dyrekcja tworzy politykę bezpieczeństwa i ocenia ryzyko. Dokument mówi, co należy chronić i jakie są zasady. <strong>Sam dokument nie blokuje ataków<\/strong>, dlatego trzeba wdrożyć ustalone zasady."], "bullets": []}, {"title": "Operational — operacyjne", "paragraphs": ["Człowiek wykonuje czynności według procedury: ochroniarz sprawdza kartę, pracownik przechodzi szkolenie antyphishingowe, analityk przegląda dzienniki zdarzeń."], "bullets": []}, {"title": "Technical — techniczne", "paragraphs": ["Program lub urządzenie automatycznie stosuje reguły: firewall (zapora sieciowa), MFA, szyfrowanie, antywirus, uprawnienia w systemie, EDR. <strong>EDR<\/strong> pomaga wykrywać i obsługiwać zagrożenia na urządzeniach."], "bullets": []}, {"title": "Physical — fizyczne", "paragraphs": ["Bariera w świecie rzeczywistym: drzwi, zamek, ogrodzenie, karta dostępu, kamera, sejf. <strong>Tailgating<\/strong> to wejście za uprawnioną osobą bez własnego zezwolenia."], "bullets": []}, {"title": "Defense in Depth — obrona w głąb", "paragraphs": ["Serwerownia ma zasady, pracownika ochrony, czytnik kart i MFA do systemów. Jeśli jedna warstwa zawiedzie, pozostałe nadal mogą chronić. To właśnie <strong>obrona w głąb<\/strong>."], "bullets": []}], "remember": "Kategoria = wykonawca: zarząd / człowiek / system / fizyczna bariera.", "example": "Regulamin: zarządcza. Szkolenie: operacyjna. Firewall: techniczna. Zamek: fizyczna.", "pitfalls": "Kamera jest środkiem fizycznym, chociaż może wykrywać albo odstraszać. Jej typ to osobna kwestia.", "quiz": [{"q": "Szkolenie pracowników z phishingu jest kontrolą…", "options": ["operacyjną", "techniczną", "fizyczną"], "answer": 0, "why": "Szkolenie to czynność wykonywana z udziałem ludzi."}, {"q": "Jaką kategorią jest zapora sieciowa?", "options": ["zarządczą", "techniczną", "fizyczną"], "answer": 1, "why": "Firewall realizuje funkcję zabezpieczającą w systemie."}], "visual": "categories"}, {"id": "w1-types", "track": 1, "title": "7 typów kontroli", "subtitle": "Przed incydentem, podczas, po i zamiast", "slides": "Wykład 1 · slajdy 38–41", "icon": "🚨", "sections": [{"title": "Kategoria a typ", "paragraphs": ["Kategoria pyta <strong>kto lub co<\/strong> realizuje ochronę. Typ pyta <strong>po co i kiedy<\/strong> działa zabezpieczenie. To dwie osobne osie. Ten sam zamek jest fizyczny (kategoria) i prewencyjny (typ)."], "bullets": []}, {"title": "Przed incydentem", "paragraphs": ["<strong>Directive (dyrektywne)<\/strong> narzucają zasady, np. procedura logowania. <strong>Deterrent (odstraszające)<\/strong> zniechęcają, np. tabliczka o monitoringu. <strong>Preventive (prewencyjne)<\/strong> próbują zatrzymać incydent, np. MFA, zamek, firewall."], "bullets": []}, {"title": "W trakcie i po incydencie", "paragraphs": ["<strong>Detective (wykrywające)<\/strong> sygnalizują atak, np. IDS, SIEM, alarm. <strong>Corrective (korygujące)<\/strong> ograniczają jego skutki, np. blokada przejętego konta lub kwarantanna złośliwego programu. <strong>Recovery (odtworzeniowe)<\/strong> przywracają działanie, np. odtworzenie z backupu."], "bullets": []}, {"title": "Compensating — kompensujące", "paragraphs": ["To zabezpieczenie <strong>zastępcze<\/strong>, używane gdy docelowego nie można wdrożyć. Np. zepsuł się czytnik kart, więc ochroniarz sprawdza osoby z listą uprawnionych. Kompensujące mogą działać na różnych etapach."], "bullets": []}, {"title": "Nowe skróty ze slajdów", "paragraphs": ["<strong>IDS<\/strong> wykrywa podejrzany ruch lub próby włamania. <strong>SIEM<\/strong> zbiera i analizuje zdarzenia bezpieczeństwa z wielu systemów. <strong>IR<\/strong> (incident response) to reagowanie na incydenty. <strong>DR<\/strong> (disaster recovery) to odtwarzanie po awarii. <strong>BCP<\/strong> (business continuity plan) to plan ciągłości działania."], "bullets": []}], "remember": "Dyrektywne mówią, odstraszające zniechęcają, prewencyjne zapobiegają, wykrywające alarmują, korygujące ograniczają skutki, kompensujące zastępują, odtworzeniowe przywracają.", "example": "Kamera nad drzwiami może jednocześnie odstraszać (gdy jest widoczna) i pomagać wykrywać (gdy ktoś monitoruje obraz).", "pitfalls": "Nie myl korygujących z odtworzeniowymi: blokada ataku ≠ przywrócenie utraconych danych.", "quiz": [{"q": "Jaki typ ma odtworzenie danych z kopii zapasowej?", "options": ["wykrywający", "odtworzeniowy", "odstraszający"], "answer": 1, "why": "Celem recovery jest przywrócenie normalnego działania."}, {"q": "Ochroniarz zastępuje niesprawny czytnik. Jaki to typ?", "options": ["kompensujący", "dyrektywny", "wykrywający"], "answer": 0, "why": "Compensating zastępuje niedostępne docelowe zabezpieczenie."}], "visual": "types"}, {"id": "w1-people", "track": 1, "title": "Ludzie, role i służby", "subtitle": "Kto odpowiada za ochronę informacji", "slides": "Wykład 1 · slajdy 42–46, 49–50", "icon": "👥", "sections": [{"title": "Kto jest kim w firmie?", "paragraphs": ["<strong>CIO<\/strong> (Chief Information Officer) zarządza obszarem IT. <strong>CTO<\/strong> (Chief Technology Officer) zajmuje się technologiami i ich wykorzystaniem. <strong>CISO<\/strong> (Chief Information Security Officer) kieruje bezpieczeństwem informacji. <strong>ISSO<\/strong> to osoba wspierająca bezpieczeństwo systemów informacyjnych."], "bullets": []}, {"title": "Pełnomocnicy w polskich instytucjach", "paragraphs": ["Pełnomocnik ds. cyberbezpieczeństwa może koordynować ochronę systemów i kontakt z CSIRT. Pełnomocnik ds. bezpieczeństwa ma często szerszy zakres. Pełnomocnik ochrony informacji niejawnych zajmuje się formalną ochroną informacji wymagających szczególnej ochrony ustawowej."], "bullets": []}, {"title": "ABW i SKW", "paragraphs": ["<strong>ABW<\/strong> (Agencja Bezpieczeństwa Wewnętrznego) pełni istotne role przy ochronie informacji niejawnych poza sferą wojskową. <strong>SKW<\/strong> (Służba Kontrwywiadu Wojskowego) ma właściwe zadania w sferze wojskowej. Na slajdach są też AW, SWW i CBA jako inne służby specjalne."], "bullets": []}, {"title": "SOC, CSIRT, DevSecOps", "paragraphs": ["<strong>SOC<\/strong> (Security Operations Center) to centrum monitorowania i analizowania zagrożeń. <strong>CSIRT<\/strong> to zespół reagowania na incydenty komputerowe. <strong>DevSecOps<\/strong> to podejście, w którym bezpieczeństwo uwzględnia się już podczas projektowania i tworzenia oprogramowania (shift left)."], "bullets": []}, {"title": "Użytkownik i compliance", "paragraphs": ["Nawet najlepszy firewall nie pomoże w każdej sytuacji, jeśli pracownik bezmyślnie uruchomi złośliwy plik. <strong>Compliance<\/strong> to przestrzeganie obowiązujących zasad i wymagań. Zarząd i pracownicy mają różne, uzupełniające się odpowiedzialności."], "bullets": []}], "remember": "CISO = szef bezpieczeństwa; SOC = obserwuje; CSIRT = reaguje; DevSecOps = wbudowuje bezpieczeństwo wcześniej.", "example": "W szpitalu SOC może wykryć niepokojący alarm; zespół reagowania analizuje incydent, a dyrekcja odpowiada za organizacyjne decyzje.", "pitfalls": "Nie zakładaj, że CISO, CIO i CTO to to samo stanowisko — nazwy odnoszą się do różnych zakresów odpowiedzialności.", "quiz": [{"q": "Jaki zespół przede wszystkim monitoruje zagrożenia?", "options": ["SOC", "HR", "księgowość"], "answer": 0, "why": "SOC to centrum operacji bezpieczeństwa."}, {"q": "Co oznacza DevSecOps?", "options": ["Dodawanie bezpieczeństwa dopiero na koniec", "Włączanie bezpieczeństwa w rozwój i utrzymanie oprogramowania", "Wysyłanie wszystkich plików do CSIRT"], "answer": 1, "why": "Ideą DevSecOps jest wbudowanie ochrony od wczesnych etapów."}], "visual": null}, {"id": "w1-care", "track": 1, "title": "Należyta staranność", "subtitle": "Najpierw sprawdź ryzyko, potem działaj", "slides": "Wykład 1 · slajdy 46–48", "icon": "🧭", "sections": [{"title": "Dlaczego samo „mamy zasady” nie wystarcza?", "paragraphs": ["Firma może stworzyć perfekcyjny regulamin, ale jeśli nikt nie instaluje aktualizacji i nie weryfikuje kopii zapasowych, ochrona jest tylko na papierze. Liczy się rzeczywiste działanie i możliwość wykazania, co zrobiono."], "bullets": []}, {"title": "Due Diligence — należyte rozpoznanie", "paragraphs": ["To <strong>zbadanie sytuacji<\/strong>: analiza ryzyka, ocena dostawcy, poszukiwanie słabych punktów. Porównanie z autem: jedziesz na przegląd i dowiadujesz się, że hamulce wymagają naprawy."], "bullets": []}, {"title": "Due Care — należyta staranność", "paragraphs": ["To <strong>podjęcie i utrzymywanie adekwatnych działań<\/strong>: instalacja poprawek, testowanie przywracania z backupu, odbieranie dostępów byłym pracownikom. Porównanie: po przeglądzie faktycznie naprawiasz hamulce."], "bullets": []}, {"title": "Przykłady z wykładu", "paragraphs": ["Dobre działania: krytyczne poprawki w rozsądnym terminie, szkolenia z dokumentacją, testowanie backupów, weryfikacja dostawców i szybkie odebranie zbędnych uprawnień.", "Zaniedbania: znana krytyczna luka miesiącami bez naprawy, wspólne hasło administratora, nieprzetestowany backup, aktywne konto byłego pracownika, zignorowany audyt."], "bullets": []}], "remember": "Due Diligence = rozpoznaj. Due Care = działaj rozsądnie i udokumentuj.", "example": "Przegląd techniczny wykazuje problem z hamulcami (diligence), a ich wymiana to care.", "pitfalls": "Należyta staranność nie oznacza gwarancji, że nigdy nie będzie ataku. Oznacza podejmowanie rozsądnych, adekwatnych działań.", "quiz": [{"q": "Firma przeprowadza analizę ryzyka dostawcy. To…", "options": ["due diligence", "due care", "hashowanie"], "answer": 0, "why": "Analiza i rozpoznanie zagrożeń to due diligence."}, {"q": "Firma wdraża łatkę na znaną lukę. To przykład…", "options": ["due care", "brute force", "tokenizacji"], "answer": 0, "why": "Wdrożenie właściwego zabezpieczenia to due care."}], "visual": null}, {"id": "w2-crypto", "track": 2, "title": "Kryptografia od podstaw", "subtitle": "Tekst jawny, szyfrogram, algorytm i klucz", "slides": "Wykład 2 · slajdy 3–4", "icon": "🔐", "sections": [{"title": "Co to znaczy zaszyfrować?", "paragraphs": ["Piszesz „Spotkajmy się o 18:00” — to <strong>plaintext (tekst jawny)<\/strong>. Komputer przekształca ją zgodnie z algorytmem i kluczem. Wynik, którego bez odpowiedniego klucza nie da się zwyczajnie przeczytać, to <strong>ciphertext (szyfrogram)<\/strong>. Odwrócenie tego procesu nazywamy <strong>decryption (deszyfrowaniem)<\/strong>."], "bullets": []}, {"title": "Algorytm ≠ klucz", "paragraphs": ["<strong>Algorytm<\/strong> to zestaw instrukcji, jak wykonać przekształcenie — jak przepis na naleśniki. <strong>Klucz<\/strong> to specjalna wartość używana przez algorytm. Dla porównania: wszyscy znają model zamka, ale tylko odpowiedni klucz go otworzy.", "Klucz jest zapisywany cyfrowo, zwykle jako ciąg bitów, czyli zer i jedynek. Nie musi być hasłem, które człowiek wpisuje na klawiaturze."], "bullets": []}, {"title": "Dlaczego sam algorytm nie powinien być tajny?", "paragraphs": ["Bezpieczeństwo nowoczesnej kryptografii powinno polegać na ochronie właściwych kluczy, a nie na ukrywaniu tego, jak działa metoda. To pozwala specjalistom badać algorytm i wykrywać jego wady."], "bullets": []}, {"title": "Słowa, które usłyszysz na wykładzie", "paragraphs": ["<strong>Cipher<\/strong> to szyfr — algorytm szyfrowania. <strong>Encryption<\/strong> to szyfrowanie. <strong>Decryption<\/strong> to deszyfrowanie. <strong>Cryptanalysis<\/strong> to kryptoanaliza, czyli próba złamania kryptograficznej ochrony."], "bullets": []}], "remember": "Tekst jawny → (algorytm + klucz) → szyfrogram → (odszyfrowanie) → tekst jawny.", "example": "Wysyłasz poufny plik: osoba podsłuchująca przesyłanie widzi zaszyfrowane dane, a uprawniony odbiorca używa odpowiedniego klucza.", "pitfalls": "Szyfrogram nie musi wyglądać dosłownie jak losowe znaczki wyświetlone na ekranie: jest ciągiem danych, często prezentowanych w określonym kodowaniu.", "quiz": [{"q": "Co oznacza plaintext?", "options": ["Zaszyfrowaną wiadomość", "Czytelną wiadomość przed szyfrowaniem", "Klucz prywatny"], "answer": 1, "why": "Plaintext to tekst jawny."}, {"q": "Co odróżnia algorytm od klucza?", "options": ["Algorytm to instrukcja, klucz to wartość używana w operacji", "To synonimy", "Klucz to zawsze nazwa pliku"], "answer": 0, "why": "Metoda szyfrowania może być publiczna, a konkretny klucz ma pozostać chroniony."}], "visual": "crypto"}, {"id": "w2-symmetric", "track": 2, "title": "Jeden klucz czy dwa?", "subtitle": "Szyfrowanie symetryczne i asymetryczne", "slides": "Wykład 2 · slajdy 5–6", "icon": "🗝️", "sections": [{"title": "Symetryczne — jedna wspólna tajemnica", "paragraphs": ["W <strong>symmetric encryption<\/strong> nadawca i odbiorca mają <strong>ten sam sekret K<\/strong>. Nadawca nim szyfruje, odbiorca nim odszyfrowuje. Tak jak dwie osoby posiadające kopie jednego klucza do sejfu.", "Zaleta: jest szybkie i dobrze nadaje się do szyfrowania dużej ilości danych. Przykład ze slajdów: <strong>AES (Advanced Encryption Standard)<\/strong>."], "bullets": []}, {"title": "Dlaczego jeden klucz jest problemem?", "paragraphs": ["Obie osoby muszą najpierw bezpiecznie zdobyć ten sam klucz. Jeśli prześlesz go niezabezpieczonym kanałem, ktoś może go podejrzeć. To <strong>problem dystrybucji klucza<\/strong>."], "bullets": []}, {"title": "Asymetryczne — dwa pasujące klucze", "paragraphs": ["W <strong>asymmetric encryption<\/strong> występuje para: <strong>public key<\/strong> (klucz publiczny) i <strong>private key<\/strong> (klucz prywatny). Publiczny można udostępnić; prywatny zachowuje właściciel.", "Gdy Ania chce zaszyfrować wiadomość <em>dla Ciebie<\/em>, używa <strong>Twojego klucza publicznego<\/strong>. Ty odszyfrowujesz ją <strong>swoim kluczem prywatnym<\/strong>. To analogia do skrzynki, do której każdy może wrzucić list, ale tylko właściciel może go wyjąć."], "bullets": []}, {"title": "Czym fizycznie jest klucz prywatny?", "paragraphs": ["Nie jest metalowym kluczem ani koniecznie PIN-em. To sekretna wartość matematyczna, zapisana cyfrowo, często wygenerowana przez komputer. Może być przechowywana w chronionym pliku lub układzie bezpieczeństwa urządzenia.", "PIN lub Face ID mogą odblokowywać możliwość jego <em>użycia<\/em>, ale nie muszą być tym samym co klucz prywatny."], "bullets": []}, {"title": "Zalety i ograniczenia", "paragraphs": ["Asymetryczne podejście rozwiązuje problem wcześniejszego przekazania jednego wspólnego sekretu, ale jest kosztowniejsze obliczeniowo. Na slajdach występują przykłady <strong>RSA<\/strong> i <strong>ECC (Elliptic Curve Cryptography)<\/strong>."], "bullets": []}], "remember": "Symetryczne: jeden wspólny klucz (AES). Asymetryczne: publiczny + prywatny (RSA, ECC).", "example": "Ania chce wysłać Ci tajną wiadomość → Ania szyfruje Twoim publicznym → tylko Twój odpowiadający prywatny odszyfrowuje.", "pitfalls": "Przy podpisie cyfrowym rola klucza prywatnego jest inna niż przy odszyfrowywaniu. Nie myl szyfrowania z podpisywaniem.", "quiz": [{"q": "Ania szyfruje wiadomość przeznaczoną dla Ciebie. Którego klucza użyje?", "options": ["Swojego prywatnego", "Twojego publicznego", "Twojego prywatnego"], "answer": 1, "why": "Dane do Ciebie szyfruje się Twoim publicznym kluczem."}, {"q": "Który algorytm kojarzymy na wykładzie z szyfrowaniem symetrycznym?", "options": ["AES", "RSA", "SHA-256"], "answer": 0, "why": "AES to popularny szyfr symetryczny."}], "visual": "keys"}, {"id": "w2-hybrid", "track": 2, "title": "Szyfrowanie hybrydowe", "subtitle": "Jak łączy się szybkość z wygodą dwóch kluczy", "slides": "Wykład 2 · slajd 7", "icon": "📦", "sections": [{"title": "Po co łączyć dwa sposoby?", "paragraphs": ["Wyobraź sobie, że wysyłasz film o wielkości 5 GB. Asymetryczne szyfrowanie całego filmu byłoby niepraktyczne. Symetryczne jest dużo szybsze — ale skąd odbiorca ma wziąć sekretny klucz?", "Rozwiązaniem jest podejście <strong>hybrydowe<\/strong>: wykorzystaj szybkie szyfrowanie symetryczne dla właściwych danych i kryptografię asymetryczną do zabezpieczenia albo uzgodnienia niewielkiego sekretu."], "bullets": []}, {"title": "Schemat ze slajdu krok po kroku", "paragraphs": ["<strong>1.<\/strong> Nadawca tworzy tymczasowy <strong>klucz sesji<\/strong> i szyfruje nim plik symetrycznie. <strong>2.<\/strong> Zabezpiecza ten krótki klucz przy użyciu publicznego klucza odbiorcy. <strong>3.<\/strong> Odbiorca używa swojego klucza prywatnego do odzyskania klucza sesji. <strong>4.<\/strong> Odszyfrowuje nim duży plik."], "bullets": []}, {"title": "Co to jest TLS?", "paragraphs": ["<strong>TLS (Transport Layer Security)<\/strong> to protokół chroniący transmisję danych, np. podczas połączenia ze stroną HTTPS. Prezentacja używa szyfrowania hybrydowego do zilustrowania tej idei.", "Dopowiedzenie: współczesny TLS często wykorzystuje wymianę kluczy, np. ECDHE, do uzgodnienia sekretu, zamiast dokładnie takiego samego sposobu przesyłania klucza jak w modelu ze slajdu."], "bullets": []}], "remember": "Duże dane → szybko szyfrujemy symetrycznie. Krótki sekret → zabezpieczamy lub uzgadniamy asymetrycznie.", "example": "Duża walizka z dokumentami i mały kluczyk: walizkę zamykamy szybko; mały kluczyk przekazujemy w bezpieczny sposób.", "pitfalls": "Hybrydowe nie jest trzecim, całkowicie niezależnym rodzajem matematyki: łączy zastosowania obu metod.", "quiz": [{"q": "Co zazwyczaj szyfruje się symetrycznie w podejściu hybrydowym?", "options": ["Właściwą dużą treść", "Tylko podpis CA", "Nigdy nic"], "answer": 0, "why": "Szyfrowanie symetryczne jest szybkie, więc nadaje się do dużych plików."}, {"q": "Czym jest klucz sesji?", "options": ["Zawsze PIN-em użytkownika", "Tymczasowym kluczem dla określonej komunikacji", "Wyłącznie nazwą certyfikatu"], "answer": 1, "why": "Klucz sesji to sekret używany podczas określonej sesji."}], "visual": "hybrid"}, {"id": "w2-attacks", "track": 2, "title": "Ataki i długość klucza", "subtitle": "Brute force, słownik i przestrzeń kluczy", "slides": "Wykład 2 · slajdy 4, 8", "icon": "🎲", "sections": [{"title": "Brute Force — próbowanie możliwości", "paragraphs": ["<strong>Atak siłowy (brute force)<\/strong> polega na sprawdzaniu kolejnych możliwych kombinacji, aż znajdzie się właściwą. Przykład: do kłódki z kodem 000–999 próbujesz wszystkie możliwe ustawienia.", "W kryptografii liczba kombinacji może być astronomiczna. Skuteczność ataku zależy m.in. od liczby prób, jakie można wykonać."], "bullets": []}, {"title": "Dictionary Attack — próbowanie prawdopodobnych haseł", "paragraphs": ["<strong>Atak słownikowy<\/strong> zaczyna się od haseł i fraz prawdopodobnych: „123456”, „qwerty” albo popularnych słów. Zamiast próbować każdą kombinację od początku, atakujący wykorzystuje przewidywalność ludzkich wyborów."], "bullets": []}, {"title": "Bit — co to takiego?", "paragraphs": ["<strong>Bit<\/strong> może przyjmować 0 albo 1. 1 bit to 2 możliwości. 2 bity to 4 możliwości (00, 01, 10, 11). 3 bity to 8 możliwości. Każdy dodatkowy bit podwaja przestrzeń możliwych wartości."], "bullets": []}, {"title": "Przestrzeń kluczy — key space", "paragraphs": ["Klucz długości <strong>n bitów<\/strong> ma <strong>2ⁿ<\/strong> możliwych wartości. AES-128 ma przestrzeń 2¹²⁸, a AES-256 2²⁵⁶. Dlatego AES-256 nie jest tylko „dwa razy silniejszy” od AES-128 w sensie liczby możliwych kluczy.", "Slajd wskazuje minimalne długości: RSA 2048 bitów i ECC 256 bitów. Nie porównuj długości kluczy różnych algorytmów wprost, bo ich matematyka jest odmienna."], "bullets": []}, {"title": "Entropia", "paragraphs": ["W kontekście haseł <strong>entropia<\/strong> to miara nieprzewidywalności. „123456” ma niską nieprzewidywalność. Długie, losowo wygenerowane hasło jest trudniejsze do odgadnięcia."], "bullets": []}], "remember": "Każdy dodatkowy bit podwaja liczbę możliwych kluczy: 2ⁿ. Brute force = wszystkie próby; słownikowy = najpierw popularne propozycje.", "example": "Kod 000–999: 1000 możliwości. Jeśli wiesz, że ludzie często wybierają 123 i 000, zaczynasz od nich w ataku słownikowym.", "pitfalls": "Długość klucza RSA nie porównuje się bezpośrednio do długości AES.", "quiz": [{"q": "Ile możliwych wartości ma klucz 3-bitowy?", "options": ["3", "6", "8"], "answer": 2, "why": "2³ = 8, bo każdy bit podwaja liczbę możliwości."}, {"q": "Próbowanie typowych haseł z listy to…", "options": ["atak słownikowy", "certyfikacja PKI", "tokenizacja"], "answer": 0, "why": "Dictionary attack polega na testowaniu prawdopodobnych haseł."}], "visual": "bits"}, {"id": "w2-hash", "track": 2, "title": "Hashowanie bez tajemnic", "subtitle": "Cyfrowy odcisk pliku, SHA-256, MD5, kolizje", "slides": "Wykład 2 · slajdy 9–10", "icon": "🧬", "sections": [{"title": "Co robi funkcja skrótu?", "paragraphs": ["<strong>Hash function<\/strong> bierze dane dowolnej długości i zwraca wynik o z góry określonej długości — <strong>hash<\/strong>. Traktuj go jak cyfrowy odcisk palca pliku. Nawet drobna zmiana danych zwykle powoduje zupełnie inny wynik."], "bullets": []}, {"title": "Dlaczego hash to nie szyfrowanie?", "paragraphs": ["Szyfrowanie jest <strong>odwracalne<\/strong> z właściwym kluczem. Hashowanie ma charakter <strong>jednokierunkowy<\/strong>: nie służy do odzyskiwania oryginału z wyniku. Nie ma zwykłego „klucza do odszyfrowania hasha”."], "bullets": []}, {"title": "Jak sprawdzać integralność pliku?", "paragraphs": ["<strong>1.<\/strong> Nadawca publikuje plik i jego wiarygodny skrót. <strong>2.<\/strong> Ty pobierasz plik. <strong>3.<\/strong> Obliczasz hash pobranej wersji. <strong>4.<\/strong> Porównujesz wyniki. Jeśli są różne — coś się zmieniło. Samo porównanie wymaga jednak zaufanego źródła oryginalnego skrótu."], "bullets": []}, {"title": "Kolizja — collision", "paragraphs": ["Jeśli <strong>dwie różne wiadomości<\/strong> mają ten sam skrót, powstaje kolizja. Takie sytuacje matematycznie mogą istnieć, dlatego bezpieczne funkcje kryptograficzne utrudniają ich znalezienie."], "bullets": []}, {"title": "SHA-256 vs MD5", "paragraphs": ["<strong>SHA-256<\/strong> ma 256-bitowy wynik i jest szeroko stosowany w kryptografii. <strong>MD5<\/strong> ma 128-bitowy wynik i jest przestarzały w zastosowaniach wymagających odporności na kolizje. Starszy SHA-1 także nie jest odpowiedni do nowych zastosowań wymagających odporności na kolizje.", "Wykład wspomina także rodzinę <strong>SHA-3<\/strong>. Do haseł użytkowników stosuje się specjalne, kosztowne funkcje takie jak Argon2id lub scrypt, a nie samo szybkie SHA-256."], "bullets": []}], "remember": "Szyfrowanie ukrywa treść i pozwala ją odzyskać z kluczem. Hash tworzy jednokierunkowy odcisk do porównań.", "example": "Masz PDF „Umowa 100 zł”. Ktoś zmienia 100 na 900 zł → hash prawie na pewno się zmieni.", "pitfalls": "Równe hashe nie stanowią same w sobie dowodu tożsamości autora; do tego potrzebujesz dodatkowych mechanizmów zaufania, np. podpisu.", "quiz": [{"q": "Czy da się zwyczajnie odszyfrować hash kluczem prywatnym?", "options": ["Tak, zawsze", "Nie, hash to nie szyfrogram", "Tylko w AES"], "answer": 1, "why": "Hashowanie i szyfrowanie są różnymi operacjami."}, {"q": "Co oznacza kolizja hashy?", "options": ["Ten sam tekst i dwa hashe", "Dwie różne wiadomości o takim samym hashu", "Złamane MFA"], "answer": 1, "why": "Kolizja to dwie różne wartości wejściowe dające jednakowy skrót."}], "visual": "hash"}, {"id": "w2-sign", "track": 2, "title": "Podpis cyfrowy", "subtitle": "Skąd wiadomo, kto podpisał i czy zmieniono dokument?", "slides": "Wykład 2 · slajd 11", "icon": "✍️", "sections": [{"title": "Po co jest podpis cyfrowy?", "paragraphs": ["Szyfrowanie pomaga ukryć treść. Ale skąd wiadomo, że dokument rzeczywiście pochodzi od banku i nie został podmieniony? <strong>Podpis cyfrowy (digital signature)<\/strong> pomaga weryfikować pochodzenie i integralność dokumentu."], "bullets": []}, {"title": "Jak działa w uproszczeniu?", "paragraphs": ["<strong>1.<\/strong> Nadawca przygotowuje dokument i jego hash. <strong>2.<\/strong> Przy użyciu <strong>własnego klucza prywatnego<\/strong> tworzy podpis matematycznie powiązany z dokumentem. <strong>3.<\/strong> Odbiorca używa <strong>klucza publicznego nadawcy<\/strong>, żeby sprawdzić podpis. <strong>4.<\/strong> Weryfikacja pomaga potwierdzić, że dokument nie został zmieniony.", "Slajd ilustruje to jako szyfrowanie skrótu kluczem prywatnym. Jest to model edukacyjny; nie każdy rzeczywisty algorytm podpisu działa dosłownie w taki sposób."], "bullets": []}, {"title": "Trzy skutki z wykładu", "paragraphs": ["<strong>Integralność<\/strong> — podpis przestaje być poprawny po nieuprawnionej zmianie. <strong>Uwierzytelnienie<\/strong> — podpis jest związany z kluczem konkretnego nadawcy. <strong>Niezaprzeczalność<\/strong> — powstaje dowód pozwalający utrudnić wiarygodne zaprzeczenie podpisaniu, przy odpowiedniej ochronie klucza i prawidłowej identyfikacji."], "bullets": []}, {"title": "Nie myl podpisu z szyfrowaniem", "paragraphs": ["Gdy <strong>Anna szyfruje wiadomość dla Oli<\/strong>, używa publicznego klucza Oli. Gdy <strong>Anna podpisuje dokument<\/strong>, używa własnego klucza prywatnego. To dwie różne operacje i dwa różne cele."], "bullets": []}], "remember": "Szyfr do odbiorcy: publiczny odbiorcy → prywatny odbiorcy. Podpis: prywatny nadawcy → weryfikacja publicznym nadawcy.", "example": "Bank wysyła PDF z podpisem. Komputer sprawdza podpis publicznym kluczem banku; zmieniony PDF nie powinien przejść weryfikacji.", "pitfalls": "Sam podpis poprawnym kluczem nie mówi jeszcze, do kogo należy klucz — potrzebne jest wiarygodne powiązanie tożsamości, np. certyfikat.", "quiz": [{"q": "Kto podpisuje dokument swoim kluczem prywatnym?", "options": ["Nadawca", "Każdy odbiorca", "Urząd skarbowy zawsze"], "answer": 0, "why": "Do utworzenia podpisu nadawca używa swojego prywatnego klucza."}, {"q": "Jakim kluczem zwykle weryfikujesz podpis nadawcy?", "options": ["Jego publicznym", "Swoim prywatnym", "Jednym wspólnym AES"], "answer": 0, "why": "Weryfikację wykonuje się pasującym kluczem publicznym nadawcy."}], "visual": "signature"}, {"id": "w2-pki", "track": 2, "title": "PKI i certyfikaty", "subtitle": "Komu należy klucz publiczny?", "slides": "Wykład 2 · slajdy 12–13", "icon": "🏛️", "sections": [{"title": "Problem podszywania się", "paragraphs": ["Ktoś wysyła Ci klucz publiczny i mówi „Jestem bankiem”. Skąd masz wiedzieć, czy nie oszukuje? Sam klucz publiczny <strong>nie jest jeszcze dowodem tożsamości<\/strong>."], "bullets": []}, {"title": "PKI — infrastruktura klucza publicznego", "paragraphs": ["<strong>Public Key Infrastructure<\/strong> to zbiór rozwiązań pomagających powiązać klucz publiczny z określonym podmiotem i zbudować zaufanie do tego powiązania. Obejmuje m.in. certyfikaty, urzędy certyfikacji i reguły weryfikacji."], "bullets": []}, {"title": "CA — Certificate Authority", "paragraphs": ["<strong>Urząd certyfikacji<\/strong> sprawdza odpowiednie informacje o podmiocie i <strong>podpisuje certyfikat<\/strong> potwierdzający określone powiązanie z kluczem publicznym. Przeglądarki mają zaufane urzędy w swoich magazynach zaufania."], "bullets": []}, {"title": "Co zawiera certyfikat?", "paragraphs": ["Np. informacje o podmiocie (<strong>subject<\/strong>), jego klucz publiczny, wystawcę, okres ważności i podpis cyfrowy CA. <strong>X.509<\/strong> określa popularny format certyfikatów. <strong>PKCS<\/strong> to rodzina standardów kryptografii klucza publicznego."], "bullets": []}, {"title": "A HTTPS?", "paragraphs": ["Przeglądarka podczas bezpiecznego połączenia sprawdza certyfikat serwera. Prawidłowy certyfikat pomaga uwierzytelnić domenę, ale <strong>nie gwarantuje uczciwości sprzedawcy ani braku oszustwa<\/strong>. Fałszywy sklep także może mieć certyfikat HTTPS."], "bullets": []}], "remember": "PKI pomaga rozwiązać pytanie: „Skąd wiem, do kogo naprawdę należy ten klucz publiczny?”.", "example": "Strona przedstawia certyfikat → przeglądarka sprawdza podpis CA i powiązanie z domeną → możliwe jest uwierzytelnienie serwera.", "pitfalls": "Certyfikat cyfrowy nie jest tym samym co prywatny klucz. Zwykle zawiera klucz publiczny, a nie sekret właściciela.", "quiz": [{"q": "Co weryfikuje urząd certyfikacji CA?", "options": ["Odpowiednie dane podmiotu i związek z kluczem publicznym", "Poprawność każdego artykułu w internecie", "Treść Twojego hasła"], "answer": 0, "why": "CA wystawia certyfikat po odpowiednim procesie weryfikacji."}, {"q": "Czy sam certyfikat HTTPS dowodzi, że sklep jest uczciwy?", "options": ["Tak, zawsze", "Nie, dotyczy uwierzytelnienia połączenia/domeny, a nie uczciwości", "Tylko gdy strona jest w języku polskim"], "answer": 1, "why": "Poprawny certyfikat to nie gwarancja uczciwości serwisu."}], "visual": "pki"}, {"id": "w2-data", "track": 2, "title": "Gdzie znajdują się dane?", "subtitle": "Spoczynek, transmisja, użycie i szyfrowanie dysków", "slides": "Wykład 2 · slajdy 14–15", "icon": "💾", "sections": [{"title": "Data at Rest — dane w spoczynku", "paragraphs": ["To dane zapisane na dysku, w bazie lub na nośniku. Przykład: zdjęcie leży w pamięci laptopa. Możemy chronić je szyfrowaniem dysku albo wybranych plików."], "bullets": []}, {"title": "Data in Transit — dane w ruchu", "paragraphs": ["To dane przesyłane przez sieć. Przykład: wysyłasz zdjęcie przyjaciółce. Przykłady zabezpieczeń na slajdzie: <strong>TLS<\/strong> lub <strong>VPN<\/strong> (wirtualna sieć prywatna, szyfrująca odpowiednio skonfigurowane połączenia)."], "bullets": []}, {"title": "Data in Use — dane w użyciu", "paragraphs": ["To dane przetwarzane właśnie w pamięci operacyjnej <strong>RAM<\/strong> lub procesorze. Wyobraź sobie dysk jako szafę z dokumentami, a RAM jako blat biurka, na którym leży aktualnie otwarty dokument."], "bullets": []}, {"title": "FDE — Full Disk Encryption", "paragraphs": ["Pełne szyfrowanie dysku chroni zapisane dane, szczególnie gdy ktoś ukradnie wyłączony sprzęt. Przykłady: <strong>BitLocker<\/strong> i <strong>FileVault<\/strong>. Gdy komputer jest już odblokowany, trzeba chronić także aktywną sesję."], "bullets": []}, {"title": "EFS i SED", "paragraphs": ["<strong>EFS (Encrypting File System)<\/strong> służy do szyfrowania wybranych plików lub folderów w odpowiednich systemach Windows. <strong>SED (Self-Encrypting Drive)<\/strong> to dysk obsługujący szyfrowanie sprzętowe."], "bullets": []}, {"title": "Backup vs redundancy", "paragraphs": ["<strong>Backup<\/strong> to kopia zapasowa pozwalająca odzyskać dane. <strong>Redundancy<\/strong> to nadmiarowość, np. drugi serwer dostępny, gdy pierwszy ulegnie awarii. Drugi serwer nie zastępuje automatycznie backupu: błędnie usunięte dane mogą zostać usunięte na obu."], "bullets": []}], "remember": "At rest = zapisane. In transit = przesyłane. In use = przetwarzane. FDE = całe dyski.", "example": "Zdjęcie na dysku → at rest; wysyłasz je → in transit; obrabiasz je w edytorze → in use.", "pitfalls": "Szyfrowanie dysku nie chroni automatycznie przed kimś, kto przejął już odblokowaną sesję użytkownika.", "quiz": [{"q": "Zdjęcie zapisywane w pamięci telefonu to…", "options": ["data at rest", "data in transit", "data in use wyłącznie"], "answer": 0, "why": "Dane zapisane na nośniku to data at rest."}, {"q": "Co oznacza FDE?", "options": ["Szyfrowanie całego dysku", "Podpis cyfrowy", "Atak słownikowy"], "answer": 0, "why": "Full Disk Encryption szyfruje cały dysk."}], "visual": "data"}, {"id": "w2-password", "track": 2, "title": "Salting i key stretching", "subtitle": "Jak utrudnić ataki na hasła", "slides": "Wykład 2 · slajd 16", "icon": "🧂", "sections": [{"title": "Dlaczego hasło nie wystarcza?", "paragraphs": ["Ludzie wybierają przewidywalne hasła, np. „kot123”. Gdy baza wycieknie, atakujący mogą próbować je odgadywać. Serwis powinien przechowywać bezpiecznie przetworzone hasła, a nie zwykłą czytelną listę."], "bullets": []}, {"title": "Salt — losowa sól", "paragraphs": ["<strong>Salting<\/strong> polega na dodaniu do hasła odrębnej losowej wartości przed jego przetworzeniem. Dwie osoby mają hasło „kot123”, ale różne sole — w efekcie przechowywane wartości są różne. Sól nie musi być tajna; ważna jest jej losowość i indywidualność."], "bullets": []}, {"title": "Jak serwis sprawdza login bez znajomości hasła?", "paragraphs": ["<strong>1.<\/strong> Przy rejestracji tworzy sól i oblicza wynik bezpiecznej funkcji haszującej hasła. <strong>2.<\/strong> Zapisuje sól i wynik. <strong>3.<\/strong> Przy kolejnym logowaniu przetwarza wpisane hasło z tą samą solą. <strong>4.<\/strong> Porównuje wynik. Nie musi odwracać hasha do postaci hasła."], "bullets": []}, {"title": "Key Stretching", "paragraphs": ["To celowe zwiększenie kosztu obliczeniowego sprawdzania hasła. Slajd opisuje wielokrotne wykonywanie obliczeń. Cel: jeśli złodziej testuje wiele haseł, <strong>każda próba będzie droższa<\/strong>. Przykładowe nowoczesne funkcje do haseł to Argon2id i scrypt (to dodatkowe wyjaśnienie, a nie nazwy z tego slajdu)."], "bullets": []}], "remember": "Salting = unikatowość wyników. Key stretching = spowolnienie prób. Obie techniki utrudniają łamanie.", "example": "Dwie osoby mają „kot123”: pierwsza otrzymuje sól A, druga sól B, więc ich wyniki nie są identyczne.", "pitfalls": "Sól sama w sobie nie zmienia słabego hasła w mocne. Nie wolno polegać wyłącznie na niej.", "quiz": [{"q": "Po co dodaje się sól do hasła?", "options": ["Żeby te same hasła mogły mieć różne zapisane skróty", "Żeby skracać klucz AES", "Żeby każdy zobaczył hasło"], "answer": 0, "why": "Losowa sól jest unikatowym dodatkiem do hasła."}, {"q": "Co robi key stretching?", "options": ["Przyspiesza łamanie", "Zwiększa koszt sprawdzenia każdej próby", "Usuwa potrzebę hasła"], "answer": 1, "why": "Cel key stretching to utrudnienie masowych prób przez większy koszt obliczeń."}], "visual": "salt"}, {"id": "w2-other", "track": 2, "title": "Blockchain i ukrywanie danych", "subtitle": "Bloki, steganografia, maskowanie, tokenizacja", "slides": "Wykład 2 · slajdy 17–18", "icon": "⛓️", "sections": [{"title": "Blockchain — łańcuch bloków", "paragraphs": ["<strong>Blockchain<\/strong> jest rosnącą listą powiązanych kryptograficznie rekordów. Każdy blok zawiera m.in. skrót wcześniejszego bloku, więc zmiana historii narusza późniejsze powiązania. W wielu rozwiązaniach kopie rejestru są przechowywane w licznych <strong>węzłach (nodes)<\/strong>."], "bullets": []}, {"title": "Ledger i węzły", "paragraphs": ["<strong>Ledger<\/strong> to rejestr, np. transakcji. <strong>Node<\/strong> to węzeł sieci, np. komputer uczestniczący w przechowywaniu i uzgadnianiu zapisów. Blockchain nie oznacza absolutnej anonimowości ani niezniszczalności."], "bullets": []}, {"title": "Obfuscation — obfuskacja", "paragraphs": ["<strong>Obfuskacja<\/strong> to utrudnianie zrozumienia albo znalezienia informacji, niekoniecznie przez szyfrowanie. Wykład przedstawia trzy przykłady: steganografię, maskowanie i tokenizację."], "bullets": []}, {"title": "Steganography — steganografia", "paragraphs": ["Ukrywasz sam fakt istnienia wiadomości. Przykład: wiadomość jest zakodowana wewnątrz obrazu. Osoba patrząca na zdjęcie może w ogóle nie wiedzieć, że jest w nim informacja."], "bullets": []}, {"title": "Data masking — maskowanie danych", "paragraphs": ["Zasłaniasz część informacji, np. numer karty <strong>**** **** **** 1234<\/strong>. Odbiorca widzi tylko potrzebny fragment, nie cały numer."], "bullets": []}, {"title": "Tokenization — tokenizacja", "paragraphs": ["Zastępujesz prawdziwą wartość losowo wyglądającym <strong>tokenem<\/strong>. Oryginał jest w odrębnym, chronionym rejestrze. Uprawniony system może ustalić, jakie dane odpowiadają tokenowi. To inne podejście niż zwykłe szyfrowanie."], "bullets": []}], "remember": "Steganografia ukrywa istnienie. Maskowanie zasłania fragment. Tokenizacja zastępuje wartość. Blockchain wiąże kolejne bloki hashami.", "example": "Maskowanie: ****1234. Tokenizacja: numer karty zastąpiony identyfikatorem. Steganografia: wiadomość ukryta w zdjęciu.", "pitfalls": "Nie myl blockchaina z kryptowalutą: kryptowaluty są jednym z jego możliwych zastosowań.", "quiz": [{"q": "Ukrycie wiadomości wewnątrz zdjęcia to…", "options": ["steganografia", "autoryzacja", "FDE"], "answer": 0, "why": "Steganografia ukrywa wiadomość w innym nośniku."}, {"q": "Zastąpienie numeru karty identyfikatorem to…", "options": ["tokenizacja", "kolizja", "brute force"], "answer": 0, "why": "Tokenizacja używa zastępczego tokenu zamiast oryginalnej wartości."}], "visual": "blockchain"}];
const GLOSSARY = [["AAA", "Authentication, Authorization, Accounting — uwierzytelnianie, autoryzacja i rozliczalność."], ["ABW", "Agencja Bezpieczeństwa Wewnętrznego; m.in. ochrona informacji niejawnych w sferze cywilnej."], ["AES", "Advanced Encryption Standard — popularny algorytm szyfrowania symetrycznego."], ["Algorytm", "Dokładny zestaw instrukcji, według których komputer wykonuje zadanie."], ["Asset (zasób)", "Coś wartościowego do ochrony, np. dane, konto, serwer, urządzenie."], ["Authentication", "Uwierzytelnianie — sprawdzenie tożsamości użytkownika."], ["Authorization", "Autoryzacja — sprawdzenie, co użytkownikowi wolno zrobić."], ["Availability", "Dostępność — działanie systemu, gdy potrzebują go uprawnione osoby."], ["Backup", "Kopia zapasowa danych potrzebna do odtwarzania."], ["BCP", "Business Continuity Plan — plan ciągłości działania."], ["Bit", "Najmniejsza jednostka informacji cyfrowej, 0 albo 1."], ["Blockchain", "Lista bloków danych powiązanych kryptograficznie."], ["Brute force", "Atak polegający na próbowaniu kolejnych możliwości."], ["CA", "Certificate Authority — urząd certyfikacji, który wystawia i podpisuje certyfikaty."], ["Certificate", "Certyfikat cyfrowy — m.in. dane podmiotu, jego klucz publiczny i podpis wystawcy."], ["CIA", "Confidentiality, Integrity, Availability — poufność, integralność, dostępność."], ["CIO", "Chief Information Officer — dyrektor odpowiedzialny za obszar IT."], ["CISO", "Chief Information Security Officer — dyrektor ds. bezpieczeństwa informacji."], ["Cipher", "Szyfr — algorytm wykorzystywany do szyfrowania."], ["Ciphertext", "Szyfrogram — dane po zaszyfrowaniu."], ["Collision", "Kolizja — dwie różne dane wejściowe mają ten sam hash."], ["Compensating control", "Kontrola kompensująca: zastępuje docelową, gdy nie da się jej zastosować."], ["Confidentiality", "Poufność — informacje widzą tylko osoby uprawnione."], ["CSIRT", "Computer Security Incident Response Team — zespół reagowania na incydenty komputerowe."], ["CTO", "Chief Technology Officer — dyrektor ds. technologii."], ["Data at rest", "Dane w spoczynku, zapisane na nośniku."], ["Data in transit", "Dane w ruchu, przesyłane przez sieć."], ["Data in use", "Dane w użyciu, aktualnie przetwarzane."], ["Decryption", "Deszyfrowanie — przywrócenie czytelnej treści z szyfrogramu."], ["Defense in depth", "Obrona w głąb — stosowanie wielu niezależnych warstw zabezpieczeń."], ["Detective control", "Kontrola wykrywająca: sygnalizuje podejrzane zdarzenia."], ["Dictionary attack", "Atak słownikowy: próbowanie prawdopodobnych haseł lub fraz."], ["Digital signature", "Podpis cyfrowy: potwierdza integralność i pomaga uwierzytelnić nadawcę."], ["DR", "Disaster Recovery — odtwarzanie działania po awarii."], ["Due care", "Należyta staranność — wdrażanie i utrzymywanie odpowiednich środków ochrony."], ["Due diligence", "Należyte rozpoznanie — analiza zagrożeń i ryzyka."], ["ECC", "Elliptic Curve Cryptography — rodzina rozwiązań kryptografii asymetrycznej."], ["EDR", "Endpoint Detection and Response — wykrywanie zagrożeń i reagowanie na urządzeniach."], ["Encryption", "Szyfrowanie — przekształcanie danych w szyfrogram."], ["Entropy", "Entropia — miara nieprzewidywalności m.in. hasła lub klucza."], ["FDE", "Full Disk Encryption — pełne szyfrowanie dysku."], ["Firewall", "Zapora sieciowa — filtruje ruch według zdefiniowanych reguł."], ["Framework", "Ramy postępowania — porządkują działania organizacji."], ["Hash", "Skrót — wynik działania funkcji skrótu."], ["Hybrid encryption", "Szyfrowanie hybrydowe — łączenie symetrycznego i asymetrycznego."], ["Identification", "Identyfikacja — wskazanie konta lub tożsamości."], ["IDS", "Intrusion Detection System — system wykrywania włamań."], ["Integrity", "Integralność — poprawność danych i wykrywanie nieuprawnionych zmian."], ["ISSO", "Information Systems Security Officer — specjalista ds. bezpieczeństwa systemów."], ["Key stretching", "Celowe zwiększanie kosztu sprawdzania haseł."], ["Least privilege", "Zasada najmniejszych uprawnień — tylko dostęp niezbędny do zadania."], ["Log", "Dziennik zdarzeń rejestrujący działania w systemie."], ["MFA", "Multi-Factor Authentication — uwierzytelnianie różnymi rodzajami czynników."], ["MD5", "Starsza funkcja skrótu, niezalecana do zastosowań wymagających odporności na kolizje."], ["NIST CSF", "Cybersecurity Framework — ramy: zarządzaj, identyfikuj, chroń, wykrywaj, reaguj, odtwarzaj."], ["Obfuscation", "Obfuskacja — utrudnianie rozumienia lub odnajdywania informacji."], ["Operational control", "Kontrola operacyjna — wykonywana przez człowieka według procedur."], ["Patch", "Poprawka oprogramowania, np. usuwająca lukę bezpieczeństwa."], ["PKCS", "Rodzina standardów kryptografii klucza publicznego."], ["PKI", "Public Key Infrastructure — infrastruktura klucza publicznego."], ["Plaintext", "Tekst jawny — oryginalna czytelna treść."], ["Private key", "Klucz prywatny — sekret właściciela pary kluczy."], ["Public key", "Klucz publiczny — może być udostępniony innym."], ["Ransomware", "Złośliwy program blokujący lub szyfrujący dane dla wymuszenia okupu."], ["Redundancy", "Nadmiarowość, np. zapasowy serwer albo łącze."], ["RSA", "Algorytm kryptografii asymetrycznej."], ["Salting", "Dodawanie unikatowej losowej soli przed przetwarzaniem hasła."], ["SED", "Self-Encrypting Drive — dysk z szyfrowaniem sprzętowym."], ["SHA-256", "Funkcja skrótu z 256-bitowym wynikiem."], ["SIEM", "Security Information and Event Management — zbieranie i analiza zdarzeń bezpieczeństwa."], ["SOC", "Security Operations Center — centrum operacji bezpieczeństwa."], ["Steganography", "Ukrywanie wiadomości wewnątrz innego nośnika, np. obrazu."], ["Symmetric encryption", "Szyfrowanie symetryczne — jeden wspólny klucz."], ["Threat", "Zagrożenie — coś, co może zaszkodzić systemowi lub danym."], ["TLS", "Transport Layer Security — protokół ochrony komunikacji przez sieć."], ["Tokenization", "Zastępowanie danych tokenem, z odpowiednio chronionym powiązaniem do oryginału."], ["Vulnerability", "Podatność — słabość systemu lub procesu możliwa do wykorzystania."], ["VPN", "Virtual Private Network — wirtualna sieć prywatna."], ["X.509", "Popularny standard struktury certyfikatów cyfrowych."]];

