LESSONS.push(...[{"id": "w3-ryzyko", "track": 3, "title": "Ryzyko i wykrywanie zagrożeń", "subtitle": "Od słabości systemu do oceny podejrzanego zdarzenia", "slides": "Wykład 3 · strony PDF 4–5 (numer slajdu = strona PDF − 1)", "icon": "🛡️", "sections": [{"title": "Trzy różne pytania", "paragraphs": ["<strong>Podatność</strong> to słabość systemu, procesu lub człowieka. <strong>Zagrożenie</strong> to aktor lub zdarzenie, które może tę słabość wykorzystać. <strong>Ryzyko</strong> dotyczy możliwości szkody: liczą się zarówno prawdopodobieństwo wykorzystania słabości, jak i skutki.", "Nie każda podatność ma taki sam priorytet. Zastanów się, jakie dane lub usługi są narażone, kto może do nich dotrzeć i co stanie się po incydencie. Zapis „podatność × zagrożenie × skutek ≈ ryzyko” na slajdzie jest poglądowy, a nie gotowym wzorem do obliczeń."], "bullets": []}, {"title": "Sygnatura czy zachowanie?", "paragraphs": ["Wykrywanie sygnaturowe porównuje obserwowany kod ze znanym wzorcem. Dobrze rozpoznaje zagrożenia, których wzorzec już znamy, ale może przeoczyć nowe. Analiza zachowania szuka odstępstw od zwykłego działania, np. logowania o nietypowej porze z nowego urządzenia.", "Te metody się uzupełniają. Znajomość wzorca pomaga rozpoznać znane zagrożenie, a obserwacja zachowań może ujawnić coś wcześniej nieznanego."], "bullets": []}, {"title": "Anomalia wymaga kontekstu", "paragraphs": ["Nietypowe logowanie nie jest jeszcze dowodem włamania. Pracownica mogła wyjechać służbowo. Trzeba ocenić dodatkowe informacje i w razie potrzeby potwierdzić zdarzenie, np. telefonicznie z użytkownikiem. Nie ignoruj alertu, ale też nie traktuj go automatycznie jak potwierdzonego incydentu."], "bullets": []}], "remember": "Podatność to słabość; zagrożenie może ją wykorzystać; ryzyko zależy od prawdopodobieństwa i skutków.", "example": "Przykład dydaktyczny: słabe hasło chroni konto z fakturami. Napastnik jest zagrożeniem, hasło podatnością, a możliwość kradzieży faktur i jej konsekwencje składają się na ryzyko.", "pitfalls": "Alert o nowej lokalizacji nie dowodzi ataku. Poglądowego zapisu ze slajdu nie używaj jako dokładnego wzoru.", "quiz": [{"q": "Które stwierdzenie opisuje ryzyko?", "options": ["Słabość hasła sama w sobie", "Możliwość szkody zależna od prawdopodobieństwa i skutków", "Nazwa konkretnego napastnika"], "answer": 1, "why": "Ryzyko łączy możliwość zdarzenia z jego konsekwencjami. Słabość jest podatnością, a napastnik może być zagrożeniem."}, {"q": "System zauważa logowanie z nowego urządzenia o nietypowej porze. Jakie podejście ilustruje?", "options": ["Analizę zachowania", "Dopasowanie podpisu cyfrowego", "Wyłącznie sygnaturę znanego wirusa"], "answer": 0, "why": "To odstępstwo od zwykłego zachowania, a nie rozpoznanie znanego wzorca kodu."}, {"q": "Co zrobić z nietypowym logowaniem?", "options": ["Zawsze uznać je za włamanie", "Zawsze je zignorować", "Sprawdzić kontekst i w razie potrzeby potwierdzić z użytkownikiem"], "answer": 2, "why": "Podróż może wyjaśniać zmianę lokalizacji; zdarzenie wymaga oceny."}], "visual": null}, {"id": "w3-aktorzy", "track": 3, "title": "Kto atakuje i dlaczego?", "subtitle": "Dostęp, umiejętności, zasoby i motywacje", "slides": "Wykład 3 · strony PDF 6–8 (numer slajdu = strona PDF − 1)", "icon": "🛡️", "sections": [{"title": "Wewnętrzny nie znaczy: siedzący w biurze", "paragraphs": ["<strong>Insider</strong> ma lub niedawno miał autoryzowany dostęp: może być pracownikiem, byłym pracownikiem, kontraktorem albo partnerem. Aktor zewnętrzny musi dopiero zdobyć dostęp.", "O klasyfikacji nie rozstrzyga samo fizyczne położenie. Obcy napastnik używający narzędzia zdalnego dostępu nie staje się przez to uprawnionym pracownikiem. Insider zna środowisko i ma pewien poziom uprawnień, dlatego może wyrządzić duże szkody."], "bullets": []}, {"title": "Umiejętności i zasoby tworzą skalę", "paragraphs": ["Aktor o małych możliwościach często korzysta z gotowych narzędzi bez zrozumienia ich działania. Aktor o dużych możliwościach może opracowywać własne techniki, korzystać ze specjalistów i prowadzić działania długo.", "Grupa może dzielić role: jedna osoba pisze kod, druga przygotowuje oszustwa, kolejna pozyskuje informacje. Obrona powinna odpowiadać realistycznym przeciwnikom, a nie jedynie najbardziej spektakularnemu scenariuszowi."], "bullets": []}, {"title": "Motyw a strategia", "paragraphs": ["Motyw odpowiada na pytanie „dlaczego?”: pieniądze, ciekawość, zemsta, rozgłos, chaos lub polityka. Strategia odpowiada na pytanie „jak osiągnąć cel?”: zakłócenie usługi, eksfiltracja, dezinformacja, wymuszenie lub oszustwo.", "Ta sama strategia może służyć różnym celom. Zakłócenie strony może wynikać zarówno z zemsty, jak i motywacji politycznej. Incydent może też być skutkiem błędu, a nie świadomego działania napastnika."], "bullets": []}], "remember": "Oddziel: kim jest aktor, jaki ma dostęp, jakie zasoby, dlaczego działa i jak realizuje cel.", "example": "Przykład dydaktyczny: zwolniony pracownik kradnie dokumenty z pozostawionego konta. Jest insiderem; motywem może być zemsta, a strategią eksfiltracja.", "pitfalls": "Nie wnioskuj o motywacji wyłącznie z metody ataku i nie utożsamiaj adresu IP z typem aktora.", "quiz": [{"q": "Która osoba może być insiderem?", "options": ["Wyłącznie etatowy informatyk", "Były pracownik, który niedawno miał dostęp", "Każdy anonimowy internauta"], "answer": 1, "why": "Wykład obejmuje także byłych pracowników, kontraktorów i partnerów."}, {"q": "Która para rozdziela motyw i strategię?", "options": ["Zemsta — zakłócenie usługi", "Eksfiltracja — kradzież danych", "Włamanie — atak"], "answer": 0, "why": "Zemsta wyjaśnia powód, zakłócenie usługi sposób działania."}, {"q": "Dlaczego zasoby aktora mają znaczenie?", "options": ["Gwarantują powodzenie każdego ataku", "Decydują tylko o jego lokalizacji", "Umożliwiają bardziej złożone i długotrwałe działania"], "answer": 2, "why": "Czas, finansowanie i specjaliści zwiększają możliwości, lecz nie gwarantują sukcesu."}], "visual": null}, {"id": "w3-grupy", "track": 3, "title": "Hakerzy, haktywiści i APT", "subtitle": "Zgoda właściciela, cele grup i trwały dostęp", "slides": "Wykład 3 · strony PDF 9–13 (numer slajdu = strona PDF − 1)", "icon": "🛡️", "sections": [{"title": "Liczy się autoryzacja", "paragraphs": ["Słowo „haker” nie musi oznaczać przestępcy. <strong>White hat</strong> działa za zgodą właściciela, np. podczas testów penetracyjnych. <strong>Black hat</strong> działa bez zgody, zwykle w złej wierze. Określenie <strong>gray hat</strong> opisuje działania bez zgody, choć bez deklarowanych złych intencji.", "Dobra intencja nie zastępuje zgody. Osoba używająca gotowych narzędzi bez ich zrozumienia, potocznie script kiddie, także może wyrządzić szkody. Co więcej, sama może pobrać narzędzie zawierające trojana."], "bullets": []}, {"title": "Grupy różnią się celem", "paragraphs": ["Haktywiści dążą przede wszystkim do celów politycznych lub ideologicznych. Mogą ujawniać skradzione dane, zakłócać usługi i podmieniać treść stron. Zorganizowani cyberprzestępcy traktują ataki jako źródło dochodu. Nieuczciwa konkurencja może finansować kradzież tajemnic, sabotaż lub dezinformację.", "Nie przypisuj każdej grupie jednego schematu zachowania. Na przykład nazwa Anonymous obejmuje luźno powiązane grupy, a samo użycie nazwy nie rozstrzyga, kto odpowiada za dany incydent."], "bullets": []}, {"title": "Aktor państwowy i APT", "paragraphs": ["Aktorzy państwowi działają na rzecz rządu, wojska lub służb. Wykład wskazuje duże zasoby, wysoki poziom umiejętności i długi horyzont działania. Pośrednicy utrudniają wykazanie związku z państwem i pozwalają zaprzeczać udziałowi.", "<strong>APT — Advanced Persistent Threat</strong> oznacza zaawansowane, trwałe zagrożenie nastawione na długotrwały, ukryty dostęp. Nie jest nazwą pojedynczego wirusa. Istotna jest możliwość pozostania w środowisku i prowadzenia dalszych działań."], "bullets": []}], "remember": "White hat: zgoda. Haktywizm: ideologia. Przestępczość: dochód. APT: ukryty, trwały dostęp.", "example": "Przykład dydaktyczny: grupa utrzymuje ukryty dostęp przez długi czas, aby zbierać informacje. Taki opis pasuje do APT bardziej niż do jednorazowej infekcji.", "pitfalls": "APT nie oznacza po prostu „dowolny wirus”. Deklarowane dobre intencje nie czynią testu autoryzowanym.", "quiz": [{"q": "Co odróżnia white hat w tym wykładzie?", "options": ["Korzystanie z gotowych programów", "Zgoda właściciela na działania", "Brak jakichkolwiek narzędzi"], "answer": 1, "why": "Najważniejsza jest autoryzacja działań przez właściciela systemu."}, {"q": "Jaki cel jest charakterystyczny dla haktywizmu?", "options": ["Polityczny lub ideologiczny", "Wyłącznie sprzedaż komputerów", "Zawsze przypadkowy"], "answer": 0, "why": "Haktywizm wykorzystuje cyberataki do realizacji celów politycznych lub ideologicznych."}, {"q": "Co najlepiej opisuje APT?", "options": ["Pojedynczy załącznik", "Każda awaria zasilania", "Długotrwały, ukryty dostęp do środowiska"], "answer": 2, "why": "Wykład akcentuje trwałość i zdolność prowadzenia kolejnych działań."}], "visual": null}, {"id": "w3-insider", "track": 3, "title": "Insider, Shadow IT i BYOD", "subtitle": "Jak ograniczać zagrożenia wewnątrz organizacji", "slides": "Wykład 3 · strony PDF 14–15 (numer slajdu = strona PDF − 1)", "icon": "🛡️", "sections": [{"title": "Złośliwość i błąd to różne źródła szkody", "paragraphs": ["Złośliwy insider świadomie kradnie dane, sabotuje systemy lub pomaga konkurencji. Niezamierzone zagrożenie wewnętrzne może wynikać z braku szkoleń, nieprzestrzegania zasad albo używania firmowego sprzętu w ryzykowny sposób.", "Nie wystarczy pytać, czy pracownik jest uczciwy. Nawet uczciwa osoba może popełnić błąd lub paść ofiarą oszustwa. Zabezpieczenia powinny ograniczać skutki także takich sytuacji."], "bullets": []}, {"title": "Uprawnienia mają swój cykl życia", "paragraphs": ["Zasada najmniejszych uprawnień ogranicza dostęp do tego, co potrzebne do pracy. Jeśli konto zostanie przejęte albo użyte w złej wierze, węższe uprawnienia mogą zmniejszyć szkodę.", "Wykład wskazuje szybkie odbieranie dostępu w dniu odejścia pracownika. Szkolenia uzupełniają technologię: pomagają rozpoznawać prośby o dane, stosować procedury i zgłaszać problemy."], "bullets": []}, {"title": "Prywatny sprzęt: dwie różne sytuacje", "paragraphs": ["<strong>BYOD</strong> oznacza prywatne urządzenie używane za zgodą i pod nadzorem organizacji. <strong>Shadow IT</strong> to sprzęt lub oprogramowanie stosowane bez wiedzy i zgody działu IT — także samodzielnie uruchomiona chmura.", "Problemem jest brak nadzoru: narzędzie może nie być objęte ewidencją, aktualizacjami ani monitoringiem. Sam fakt, że urządzenie należy do pracownika, nie wystarcza do nazwania go Shadow IT."], "bullets": []}], "remember": "Insider może działać celowo albo popełnić błąd. BYOD jest uzgodnione; Shadow IT pozostaje poza wiedzą i zgodą IT.", "example": "Przykład dydaktyczny: zespół wrzuca dokumenty do prywatnej, niezatwierdzonej chmury „bo szybciej”. To Shadow IT, nawet jeśli wszyscy chcą tylko ułatwić pracę.", "pitfalls": "Szkolenia nie zastępują kontroli uprawnień. Prywatny laptop nie jest automatycznie Shadow IT.", "quiz": [{"q": "Pracownik nieumyślnie omija zasady bezpieczeństwa. To przykład:", "options": ["Wyłącznie aktora państwowego", "Niezamierzonego zagrożenia wewnętrznego", "Zawsze świadomego sabotażu"], "answer": 1, "why": "Brak złej intencji nie wyklucza szkody."}, {"q": "Prywatny laptop dopuszczony i nadzorowany przez organizację to:", "options": ["BYOD", "Shadow IT z definicji", "APT"], "answer": 0, "why": "W BYOD kluczowe są zgoda i nadzór."}, {"q": "Które działanie ogranicza skutki nadużycia konta?", "options": ["Nadanie wszystkim uprawnień administratora", "Pozostawienie dostępu po odejściu", "Zasada najmniejszych uprawnień"], "answer": 2, "why": "Mniejszy zakres dostępu ogranicza możliwy zasięg szkód."}], "visual": null}, {"id": "w3-powierzchnia", "track": 3, "title": "Powierzchnia ataku, podatności i exploity", "subtitle": "Co można zaatakować i jak wykorzystuje się słabość", "slides": "Wykład 3 · strony PDF 16–18 (numer slajdu = strona PDF − 1)", "icon": "🛡️", "sections": [{"title": "Powierzchnia a wektor", "paragraphs": ["<strong>Powierzchnia ataku</strong> to zbiór miejsc możliwego ataku: ludzie, aplikacje, sieci, urządzenia i dostępne porty. <strong>Wektor</strong> to konkretna droga wykorzystana przez napastnika.", "Wyobraź sobie budynek z drzwiami i oknami. Wszystkie punkty wejścia tworzą powierzchnię, a wybrane okno ilustruje wektor. Zamykanie niepotrzebnych portów i wyłączanie zbędnych usług ogranicza liczbę dróg wejścia."], "bullets": []}, {"title": "Podatność, zero-day i koniec wsparcia", "paragraphs": ["<strong>Exploit</strong> to kod lub technika wykorzystania podatności; nie jest samą słabością. Wykład opisuje zero-day jako błąd nieznany producentowi lub bez dostępnej poprawki w chwili odkrycia i wykorzystania.", "Po zakończeniu wsparcia — EOL — nie należy zakładać, że producent dostarczy kolejne poprawki. Dlatego migracja do wspieranego systemu jest kwestią bezpieczeństwa. Otwartość kodu może pozwolić innym utrzymywać poprawki, ale sama ich nie zapewnia."], "bullets": []}, {"title": "Zdalnie i lokalnie", "paragraphs": ["W uproszczeniu przyjętym na slajdzie exploit zdalny dociera przez sieć bez wcześniejszej uwierzytelnionej sesji, a lokalny wymaga sesji na maszynie. Rozróżnienie pokazuje różne warunki dostępu; zawsze trzeba czytać warunki konkretnej podatności.", "Skaner podatności może działać jako agent na hoście albo bezagentowo. Jego zadaniem jest znajdowanie słabości, nie automatyczne zagwarantowanie, że system jest bezpieczny."], "bullets": []}], "remember": "Powierzchnia = wszystkie możliwe punkty. Wektor = wybrana droga. Podatność = słabość. Exploit = jej wykorzystanie.", "example": "Przykład dydaktyczny: organizacja usuwa zbędną usługę dostępną z sieci. Ogranicza powierzchnię ataku, a nie zmienia motywacji napastnika.", "pitfalls": "Nie myl exploita z podatnością. Uproszczenia o exploitach traktuj jako model z wykładu, a nie opis warunków każdej luki.", "quiz": [{"q": "Co jest powierzchnią ataku?", "options": ["Jedna wybrana wiadomość phishingowa", "Suma miejsc, które można zaatakować", "Wyłącznie hasło administratora"], "answer": 1, "why": "Powierzchnia obejmuje ludzi, aplikacje, sieć i urządzenia."}, {"q": "Co to exploit?", "options": ["Kod lub technika wykorzystująca podatność", "Każdy zasób firmy", "Wyłącznie poprawka systemu"], "answer": 0, "why": "Podatność jest słabością; exploit służy jej wykorzystaniu."}, {"q": "Dlaczego koniec wsparcia systemu jest istotny?", "options": ["Zawsze usuwa wszystkie dane", "Gwarantuje odporność na nowe ataki", "Dalsze poprawki producenta mogą nie być dostępne"], "answer": 2, "why": "Brak wsparcia zwiększa znaczenie migracji i oceny ryzyka."}], "visual": null}, {"id": "w3-wektory", "track": 3, "title": "Wektory ataku i łańcuch dostaw", "subtitle": "Sieć, przynęty, wiadomości i dostawcy", "slides": "Wykład 3 · strony PDF 18–21 (numer slajdu = strona PDF − 1)", "icon": "🛡️", "sections": [{"title": "Rozpoznaj, co jest naruszane", "paragraphs": ["Podsłuch ruchu zagraża poufności, modyfikacja komunikacji integralności, a odmowa usługi dostępności. Atak on-path wiąże się z przechwytywaniem lub modyfikowaniem ruchu po drodze.", "Wykład wymienia fizyczny dostęp do stacji, sieć przewodową, Wi-Fi, dostęp zdalny, chmurę i Bluetooth. Niezmienione fabryczne hasło oraz zbędnie otwarty port również mogą ułatwiać wejście. W sieci przewodowej port security pomaga ograniczać podłączanie nieautoryzowanych urządzeń."], "bullets": []}, {"title": "Przynęta zachęca do działania", "paragraphs": ["Nośnik USB, pozornie przydatny program, dokument z makrem albo spreparowane multimedia mogą być przynętą. Trojan ukrywa złośliwe działanie w czymś pozornie użytecznym. Nie każdy plik tego typu jest złośliwy; znaczenie mają pochodzenie i okoliczności.", "E-mail, SMS, komunikator i media społecznościowe mogą przenosić linki lub załączniki. Sama dostawa wiadomości nie jest tym samym co wykonanie polecenia. Socjotechnika ma skłonić odbiorcę do otwarcia pliku albo ujawnienia danych."], "bullets": []}, {"title": "Zaufany dostawca też jest częścią ryzyka", "paragraphs": ["Atak na łańcuch dostaw uderza w dostawcę komponentu, oprogramowania lub usługi, aby dotrzeć do właściwego celu. W prezentacji przykładem jest modyfikacja firmware podzespołu jeszcze przed dostarczeniem go użytkownikowi.", "MSP to zewnętrzny dostawca usług zarządzanych, np. obsługi IT. Outsourcing może obniżać koszty, lecz nie usuwa odpowiedzialności za ocenę ryzyka u dostawcy. Im więcej powiązań, tym więcej punktów wymagających nadzoru."], "bullets": []}], "remember": "Droga do organizacji może prowadzić przez urządzenie, wiadomość, człowieka albo dostawcę.", "example": "Przykład dydaktyczny: firma zabezpiecza własne serwery, ale nie sprawdza dostawcy obsługującego je zdalnie. Atak na tego dostawcę może pośrednio zagrozić firmie.", "pitfalls": "Nie zakładaj, że znana marka lub outsourcing automatycznie zapewniają bezpieczeństwo. Nie podłączaj znalezionych nośników, aby sprawdzić ich zawartość.", "quiz": [{"q": "Ktoś podsłuchuje komunikację i poznaje hasło. Co przede wszystkim narusza?", "options": ["Dostępność", "Poufność", "Wyłącznie rozliczalność"], "answer": 1, "why": "Nieuprawnione poznanie treści jest naruszeniem poufności."}, {"q": "Napastnik modyfikuje podzespół u dostawcy przed dostawą do ofiary. To:", "options": ["Atak na łańcuch dostaw", "Zatwierdzone BYOD", "Kontrola odtworzeniowa"], "answer": 0, "why": "Droga do ofiary prowadzi przez dostawcę."}, {"q": "Co opisuje trojana?", "options": ["Każdy dokument PDF", "Każde urządzenie Bluetooth", "Złośliwy program ukryty w czymś pozornie przydatnym"], "answer": 2, "why": "O nazwie decyduje maskowanie złośliwej funkcji, a nie samo rozszerzenie pliku."}], "visual": null}, {"id": "w3-socjotechnika", "track": 3, "title": "Socjotechnika: zaufanie, pretekst i presja", "subtitle": "Jak rozpoznać manipulację człowiekiem", "slides": "Wykład 3 · strony PDF 22–23 (numer slajdu = strona PDF − 1)", "icon": "🛡️", "sections": [{"title": "Celem może być informacja albo działanie", "paragraphs": ["Inżynieria społeczna nakłania człowieka do ujawnienia informacji lub wykonania czynności, której normalnie by nie zrobił. Wykorzystuje zaufanie, presję i błędy oceny.", "Etap rozpoznania dostarcza nazwisk, procedur i informacji o organizacji. Intruzja wykorzystuje tę wiedzę do uzyskania nieautoryzowanego dostępu. To rozróżnienie pomaga zauważyć, że niewinna z pozoru rozmowa może przygotowywać późniejszy atak."], "bullets": []}, {"title": "Tożsamość a opowieść", "paragraphs": ["<strong>Impersonation</strong> to podszywanie się pod osobę, np. pracownika IT. <strong>Pretexting</strong> to wiarygodnie brzmiący scenariusz tłumaczący prośbę, przygotowany wraz z odpowiedziami na wątpliwości. Jedna rozmowa może zawierać oba elementy.", "Perswazja przedstawia spełnienie prośby jako naturalne i uprzejme. Zastraszenie wywołuje pilność lub obawę przed konsekwencją. Ani uprzejmy ton, ani groźba nie potwierdzają uprawnień rozmówcy."], "bullets": []}, {"title": "Szczegóły nie są dowodem upoważnienia", "paragraphs": ["Dumpster diving to pozyskiwanie informacji z wyrzuconych dokumentów i innych odpadów. Nazwisko z faktury czy lista pracowników mogą uwiarygodnić pretekst. To, że rozmówca zna szczegóły, nie znaczy, że wolno przekazać mu dane.", "Obrona omawiana na wykładzie obejmuje szkolenia, weryfikowanie nadawcy i zgłaszanie incydentów. Zachowaj ostrożność wobec fałszywych alarmów nakazujących kliknięcie lub instalację programu."], "bullets": []}], "remember": "Impersonation: za kogo się podaje? Pretexting: jaką historią uzasadnia prośbę?", "example": "Przykład dydaktyczny: rozmówca twierdzi, że jest z IT i potrzebuje danych „do pilnej naprawy”. Tożsamość i historia wymagają weryfikacji, nawet jeśli zna Twoje nazwisko.", "pitfalls": "Znajomość nazwisk, presja czasu i stanowisko podane przez rozmówcę nie są dowodami autoryzacji.", "quiz": [{"q": "Podawanie się za pracownika IT to:", "options": ["Impersonation", "Hashowanie", "Redundancja"], "answer": 0, "why": "Impersonation dotyczy fałszywej tożsamości."}, {"q": "Przygotowana historia z odpowiedziami na wątpliwości to:", "options": ["BYOD", "Pretexting", "EOL"], "answer": 1, "why": "Pretexting buduje wiarygodny pretekst dla prośby."}, {"q": "Co opisuje dumpster diving?", "options": ["Weryfikację podpisu cyfrowego", "Test dostępności serwera", "Zbieranie informacji z wyrzuconych materiałów"], "answer": 2, "why": "Wyrzucone dokumenty mogą zawierać szczegóły przydatne do oszustwa."}], "visual": null}, {"id": "w3-phishing", "track": 3, "title": "Phishing i ataki ukierunkowane", "subtitle": "Vishing, smishing, pharming, BEC i watering hole", "slides": "Wykład 3 · strony PDF 24–26 (numer slajdu = strona PDF − 1)", "icon": "🛡️", "sections": [{"title": "Kanał i mechanizm", "paragraphs": ["Phishing podszywa się pod zaufany podmiot, aby skłonić odbiorcę do kliknięcia lub ujawnienia informacji. <strong>Vishing</strong> wykorzystuje rozmowę telefoniczną, a <strong>smishing</strong> SMS. Spoofing to fałszowanie tożsamości nadawcy, często używane w phishingu.", "<strong>Pharming</strong> przekierowuje na fałszywą stronę, np. przez manipulację DNS. Fałszywa strona może po kradzieży danych przenieść użytkownika na prawdziwą, więc późniejsze zobaczenie poprawnej strony nie oznacza, że nic się nie stało."], "bullets": []}, {"title": "Kogo wybrano na cel?", "paragraphs": ["<strong>Spear phishing</strong> jest ukierunkowany na wybraną osobę lub małą grupę. <strong>Whaling</strong> celuje w osobę na najwyższym szczeblu. <strong>BEC</strong> oznacza przejęcie lub podszycie się pod konto biznesowe, by wydawać wiarygodnie wyglądające polecenia innym pracownikom.", "Odróżniaj cel od odgrywanej roli: wiadomość udająca prezesa wysłana do księgowości ilustruje BEC; nie musi oznaczać, że prezes jest adresatem ataku typu whaling."], "bullets": []}, {"title": "Podobna domena i zaufana witryna", "paragraphs": ["<strong>Typosquatting</strong> wykorzystuje domenę łudząco podobną do właściwej, np. z inną literą lub końcówką. Prezentacja nazywa taką domenę także cousin domain. W <strong>watering hole</strong> napastnik kompromituje witrynę, którą cel regularnie odwiedza.", "Sprawdzaj faktyczny adres nadawcy i docelowy adres odnośnika, nie tylko nazwę wyświetlaną obok wiadomości. Świadomość zagrożeń, szkolenia i ograniczenie powierzchni ataku uzupełniają zabezpieczenia techniczne."], "bullets": []}], "remember": "Telefon = vishing; SMS = smishing; przekierowanie = pharming; wybrany cel = spear phishing; najwyższe stanowisko = whaling.", "example": "Przykład dydaktyczny: księgowa otrzymuje prośbę o pilny przelew rzekomo od prezesa. Wygląd wiadomości i podpis nie wystarczają do potwierdzenia, że polecenie pochodzi od niego.", "pitfalls": "Nie myl podszywania się pod prezesa z atakiem skierowanym do prezesa. Znana strona też może zostać przejęta.", "quiz": [{"q": "Fałszywa prośba przesłana SMS-em to:", "options": ["Vishing", "Smishing", "Wyłącznie pharming"], "answer": 1, "why": "Smishing określa phishing za pomocą SMS. Vishing wykorzystuje głos."}, {"q": "Co odróżnia pharming?", "options": ["Przekierowanie na fałszywą witrynę, np. przez DNS", "Wyłącznie rozmowa telefoniczna", "Zawsze kradzież laptopa"], "answer": 0, "why": "Pharming dotyczy przekierowania, a nie kanału głosowego."}, {"q": "Przejęto stronę regularnie odwiedzaną przez wybraną grupę ofiar. To:", "options": ["BYOD", "Saltowanie", "Watering hole"], "answer": 2, "why": "Napastnik wykorzystuje witrynę odwiedzaną przez cel."}], "visual": null}]);
GLOSSARY.push(...[["Insider", "Aktor mający lub niedawno mający autoryzowany dostęp do organizacji."], ["External actor", "Aktor zewnętrzny, który musi dopiero zdobyć dostęp."], ["Eksfiltracja", "Nieuprawnione wyprowadzenie danych, np. do sprzedaży lub szantażu."], ["White hat", "Haker działający za zgodą właściciela systemu."], ["Black hat", "Haker działający bez zgody, zwykle w złej wierze."], ["Gray hat", "Działanie bez zgody właściciela, choć bez deklarowanych złych intencji; intencja nie zastępuje zgody."], ["Script kiddie", "Osoba korzystająca z gotowych narzędzi bez pełnego zrozumienia ich działania."], ["Haktywizm", "Wykorzystanie cyberataków do celów politycznych lub ideologicznych."], ["Nation-state actor", "Aktor działający na rzecz państwa, wojska lub służb."], ["APT", "Advanced Persistent Threat — zaawansowane trwałe zagrożenie, nastawione na ukryty, długotrwały dostęp."], ["Plausible deniability", "Możliwość wiarygodnego zaprzeczania udziałowi, ułatwiana przez działanie przez pośredników."], ["Shadow IT", "Sprzęt lub oprogramowanie używane bez wiedzy i zgody działu IT."], ["BYOD", "Bring Your Own Device — prywatny sprzęt używany za zgodą i pod nadzorem organizacji."], ["Attack surface", "Powierzchnia ataku: wszystkie miejsca możliwego ataku, np. ludzie, aplikacje, sieci i urządzenia."], ["Threat vector", "Wektor ataku: konkretna droga wykorzystana do zaatakowania organizacji."], ["Zero-day", "W ujęciu wykładu: luka nieznana producentowi lub bez dostępnej łaty w momencie odkrycia i wykorzystania."], ["EOL", "End of life — koniec wsparcia produktu; nie należy zakładać dalszych poprawek producenta."], ["Exploit", "Kod lub technika wykorzystująca podatność."], ["Eavesdropping", "Podsłuchiwanie komunikacji, zagrażające jej poufności."], ["On-path", "Atak polegający na przechwytywaniu lub modyfikowaniu ruchu pomiędzy stronami komunikacji."], ["DoS", "Denial of Service — odmowa usługi, atak na dostępność."], ["Trojan horse", "Koń trojański: złośliwy program ukryty w czymś pozornie przydatnym."], ["Supply chain attack", "Atak przez dostawcę komponentów, oprogramowania lub usług celu."], ["MSP", "Managed Service Provider — zewnętrzny dostawca usług zarządzanych, np. obsługi IT."], ["Social engineering", "Socjotechnika: nakłanianie ludzi do ujawniania informacji lub wykonywania ryzykownych czynności."], ["Impersonation", "Podszywanie się pod inną osobę lub rolę w celu wzbudzenia zaufania."], ["Pretexting", "Przygotowany, wiarygodnie brzmiący scenariusz uzasadniający prośbę napastnika."], ["Dumpster diving", "Pozyskiwanie informacji z wyrzuconych dokumentów lub innych odpadów."], ["Phishing", "Podszywanie się pod zaufany podmiot, aby nakłonić do kliknięcia lub ujawnienia informacji."], ["Vishing", "Phishing w rozmowie telefonicznej."], ["Smishing", "Phishing przez SMS."], ["Pharming", "Przekierowanie na fałszywą stronę, np. wskutek manipulacji DNS."], ["Typosquatting", "Wykorzystanie domeny łudząco podobnej do prawdziwej."], ["BEC", "Business Email Compromise — przejęcie lub podszycie się pod konto biznesowe w celu wydawania fałszywych poleceń."], ["Spear phishing", "Phishing ukierunkowany na konkretną osobę lub niewielką grupę."], ["Whaling", "Spear phishing wymierzony w osobę na najwyższym szczeblu."], ["Watering hole", "Kompromitacja witryny regularnie odwiedzanej przez cel ataku."]]);
LECTURE_MULTI.push(...[{"id": "lecture-multi-w3-ryzyko", "track": 3, "lesson": "w3-ryzyko", "lessonTitle": "Ryzyko i wykrywanie zagrożeń", "q": "Które pary są poprawne?", "options": ["Podatność — słabość procesu", "Ryzyko — wyłącznie liczba napastników", "Zagrożenie — zdarzenie mogące wykorzystać słabość", "Anomalia — pewne włamanie"], "answers": [0, 2], "why": "Ryzyko uwzględnia prawdopodobieństwo i skutek. Anomalia nie przesądza o incydencie. Źródło: Wykład 3 · strony PDF 4–5 (numer slajdu = strona PDF − 1)"}, {"id": "lecture-multi-w3-aktorzy", "track": 3, "lesson": "w3-aktorzy", "lessonTitle": "Kto atakuje i dlaczego?", "q": "Które stwierdzenia są zgodne z wykładem?", "options": ["Niski poziom umiejętności oznacza brak zagrożenia", "Grupa może dzielić zadania między specjalistów", "Zakłócenie usługi może mieć różne motywacje", "Insider musi działać ze złą intencją"], "answers": [1, 2], "why": "Gotowe narzędzia nadal mogą szkodzić, a incydenty wewnętrzne bywają niezamierzone. Źródło: Wykład 3 · strony PDF 6–8 (numer slajdu = strona PDF − 1)"}, {"id": "lecture-multi-w3-grupy", "track": 3, "lesson": "w3-grupy", "lessonTitle": "Hakerzy, haktywiści i APT", "q": "Wybierz poprawne pary.", "options": ["White hat — autoryzowane testy", "APT — wyłącznie jednorazowy wirus", "Haktywizm — cele ideologiczne", "Przestępczość zorganizowana — dochód z ataków"], "answers": [0, 2, 3], "why": "APT dotyczy trwałego zagrożenia, a pozostałe pary poprawnie opisują kategorie z wykładu. Źródło: Wykład 3 · strony PDF 9–13 (numer slajdu = strona PDF − 1)"}, {"id": "lecture-multi-w3-insider", "track": 3, "lesson": "w3-insider", "lessonTitle": "Insider, Shadow IT i BYOD", "q": "Co pomaga ograniczyć zagrożenia wewnętrzne?", "options": ["Szkolenie użytkowników", "Szybkie odebranie dostępu odchodzącym osobom", "Stały dostęp administratora dla każdego", "Najmniejsze niezbędne uprawnienia"], "answers": [0, 1, 3], "why": "Szkolenia i zarządzanie dostępem się uzupełniają; nadmiarowe uprawnienia zwiększają ryzyko. Źródło: Wykład 3 · strony PDF 14–15 (numer slajdu = strona PDF − 1)"}, {"id": "lecture-multi-w3-powierzchnia", "track": 3, "lesson": "w3-powierzchnia", "lessonTitle": "Powierzchnia ataku, podatności i exploity", "q": "Które działania ograniczają powierzchnię ataku według wykładu?", "options": ["Wyłączanie zbędnych usług", "Otwieranie wszystkich portów", "Zamykanie niepotrzebnych portów", "Szkolenia i aktualizacje"], "answers": [0, 2, 3], "why": "Działania ograniczają dostępne drogi lub słabości; otwieranie wszystkiego działa przeciwnie. Źródło: Wykład 3 · strony PDF 16–18 (numer slajdu = strona PDF − 1)"}, {"id": "lecture-multi-w3-wektory", "track": 3, "lesson": "w3-wektory", "lessonTitle": "Wektory ataku i łańcuch dostaw", "q": "Wybierz poprawne pary.", "options": ["Eavesdropping — podsłuchiwanie", "DoS — atak na dostępność", "MSP — zewnętrzny dostawca usług zarządzanych", "Trojan — gwarantowanie integralności"], "answers": [0, 1, 2], "why": "Trojan ukrywa złośliwe działanie; nie jest mechanizmem ochrony integralności. Źródło: Wykład 3 · strony PDF 18–21 (numer slajdu = strona PDF − 1)"}, {"id": "lecture-multi-w3-socjotechnika", "track": 3, "lesson": "w3-socjotechnika", "lessonTitle": "Socjotechnika: zaufanie, pretekst i presja", "q": "Co może zwiększać wiarygodność pretekstu napastnika?", "options": ["Znajomość nazwisk pracowników", "Znajomość wewnętrznych procedur", "Szczegóły pozyskane z wyrzuconych dokumentów", "Samo zapewnienie, że każda prośba jest legalna, daje formalne uprawnienia"], "answers": [0, 1, 2], "why": "Szczegóły wspierają manipulację, ale nie stanowią dowodu upoważnienia. Źródło: Wykład 3 · strony PDF 22–23 (numer slajdu = strona PDF − 1)"}, {"id": "lecture-multi-w3-phishing", "track": 3, "lesson": "w3-phishing", "lessonTitle": "Phishing i ataki ukierunkowane", "q": "Które pary są poprawne?", "options": ["Vishing — rozmowa telefoniczna", "Smishing — SMS", "Whaling — dowolna masowa wiadomość", "Spear phishing — wybrana osoba lub niewielka grupa"], "answers": [0, 1, 3], "why": "Whaling to szczególny atak ukierunkowany na osoby na najwyższych stanowiskach. Źródło: Wykład 3 · strony PDF 24–26 (numer slajdu = strona PDF − 1)"}].filter(q=>!LECTURE_MULTI.some(old=>old.id===q.id)));
