LESSONS.push(...[{"id": "w4-malware", "track": 4, "title": "Malware: wirus, robak i trojan", "subtitle": "Rozpoznaj sposób działania, a nie tylko nazwę", "slides": "Wykład 4 · strony PDF 4–6 (numer slajdu = strona PDF − 1)", "icon": "🛡️", "sections": [{"title": "Malware to szeroka kategoria", "paragraphs": ["Malware oznacza złośliwe oprogramowanie. Nazwy jego rodzajów opisują różne rzeczy: sposób rozprzestrzeniania, ukrytą funkcję albo skutki. Jeden program może więc pasować do kilku kategorii. Samo użycie legalnego narzędzia przez napastnika nie tworzy nowego rodzaju malware."], "bullets": []}, {"title": "Wirus a robak", "paragraphs": ["Wirus dołącza do nośnika, np. pliku lub innego kodu. Replikuje się przy wykonaniu tego nośnika. Nie musi to oznaczać świadomego kliknięcia przez człowieka przy każdym zakażeniu. Robak jest samodzielny i potrafi rozprzestrzeniać się automatycznie przez sieć. Czasem użytkownik uruchamia pierwszą kopię, ale dalsza propagacja odbywa się już bez niego."], "bullets": []}, {"title": "Trojan, PUP i bloatware", "paragraphs": ["Trojan udaje nieszkodliwy plik lub program, ukrywając szkodliwą funkcję. Może jednocześnie wykonywać obiecaną czynność, ale nie jest to konieczne. PUP/PUA to potencjalnie niechciane oprogramowanie, np. dodatek z instalatora, który zmienia stronę startową. Bloatware oznacza zbędne lub nadmiernie rozbudowane oprogramowanie, często preinstalowane; nie jest synonimem PUP.", "Podczas instalacji warto sprawdzić opcje niestandardowe i odrzucić zbędne dodatki. Nazwa „ekspresowa” nie mówi, jakie dodatkowe składniki zostaną zaakceptowane."], "bullets": []}], "remember": "Wirus potrzebuje nośnika; robak sam się rozprzestrzenia; trojan ukrywa szkodliwą funkcję.", "example": "Przykład dydaktyczny: „Darmowy konwerter” przetwarza dokument, ale potajemnie wykrada dane. Działająca funkcja konwersji nie wyklucza trojana.", "pitfalls": "Kategorie mogą się nakładać. Nie każde niechciane narzędzie jest wirusem.", "quiz": [{"q": "Kod replikuje się po wykonaniu zainfekowanego pliku. Co najlepiej pasuje?", "options": ["Wirus", "Bloatware", "Cookie"], "answer": 0, "why": "Wirus wiąże się z nośnikiem i wykonaniem jego kodu."}, {"q": "Co odróżnia robaka?", "options": ["Zawsze wymaga kliknięcia każdej ofiary", "Samodzielna automatyczna propagacja", "Musi wyświetlać reklamy"], "answer": 1, "why": "Robak może samodzielnie rozsyłać kolejne kopie; uruchomienie pierwszej bywa osobnym etapem."}, {"q": "Program działa zgodnie z reklamą, ale ukrywa kradzież danych. Czy może być trojanem?", "options": ["Nie, skoro działa", "Tylko gdy jest preinstalowany", "Tak"], "answer": 2, "why": "Trojan może wykonywać legalną funkcję i jednocześnie ukrywać szkodliwą."}], "visual": null}, {"id": "w4-sledzenie", "track": 4, "title": "Śledzenie, spyware i keyloggery", "subtitle": "Co zbiera dane i kiedy staje się zagrożeniem", "slides": "Wykład 4 · strony PDF 7–8 (numer slajdu = strona PDF − 1)", "icon": "🛡️", "sections": [{"title": "Cookie nie jest całą historią przeglądania", "paragraphs": ["Cookie może przechowywać identyfikator. To serwer kojarzy go z historią żądań i innymi informacjami. Cookies stron trzecich mogą pomagać rozpoznawać osobę między witrynami. „Supercookie” to szerokie określenie trwalszych technik identyfikacji poza zwykłymi cookies."], "bullets": []}, {"title": "Piksel i fingerprinting", "paragraphs": ["Piksel śledzący, czyli web beacon, wywołuje żądanie niewielkiego obrazu. Serwer może poznać czas, IP i informacje o przeglądarce. Fingerprinting wykorzystuje zestaw cech urządzenia lub przeglądarki do rozpoznawania. To odrębny mechanizm; samo usunięcie cookies nie usuwa wszystkich sposobów identyfikacji. Mechanizmy śledzenia nie są automatycznie malware."], "bullets": []}, {"title": "Reklamy a szpiegowanie", "paragraphs": ["Adware wyświetla reklamy, czasem niechciane i połączone ze zmianami ustawień. Spyware monitoruje użytkownika: może nagrywać ekran, robić zrzuty lub zbierać aktywność. Keylogger zapisuje klawisze i może być programem albo urządzeniem. Złośliwy keylogger bywa spyware, ale samo narzędzie nie zawsze jest złośliwe.", "Keylogger może działać selektywnie, np. tylko przy logowaniu. Mniej zebranych znaków nie oznacza mniejszego zagrożenia: kilka znaków może zawierać hasło."], "bullets": []}], "remember": "Rozróżniaj identyfikację użytkownika, reklamy i potajemne zbieranie danych.", "example": "Przykład dydaktyczny: Obraz w wiadomości ładuje się z serwera nadawcy. Samo żądanie może ujawnić, kiedy wiadomość została otwarta, bez instalowania wirusa.", "pitfalls": "Nie zakładaj, że każde śledzenie to malware ani że keylogger musi być programem.", "quiz": [{"q": "Gdzie zwykle przechowywana jest historia kojarzona z identyfikatorem cookie?", "options": ["Zawsze wewnątrz cookie", "Na serwerze", "Wyłącznie w pamięci klawiatury"], "answer": 1, "why": "Cookie może zawierać identyfikator, a historię utrzymuje serwer."}, {"q": "Co robi web beacon?", "options": ["Szyfruje dysk", "Uruchamia wyłącznie lokalny zegar", "Wywołuje żądanie, które pozwala zebrać informacje"], "answer": 2, "why": "Załadowanie zasobu może ujawnić czas, IP i informacje o przeglądarce."}, {"q": "Keylogger zbiera dane tylko na stronie logowania. Co wynika z tego faktu?", "options": ["Może nadal wykradać bardzo wrażliwe dane", "Jest bezpieczny", "Nie jest keyloggerem"], "answer": 0, "why": "Selektywność nie eliminuje szkody; celem mogą być właśnie hasła."}], "visual": null}, {"id": "w4-zdalna-kontrola", "track": 4, "title": "Backdoor, RAT i botnet", "subtitle": "Ukryte wejście i sterowanie urządzeniami", "slides": "Wykład 4 · strony PDF 9–10 (numer slajdu = strona PDF − 1)", "icon": "🛡️", "sections": [{"title": "Backdoor nie musi dawać administratora", "paragraphs": ["Backdoor to ukryty sposób obejścia zwykłych zabezpieczeń lub uwierzytelniania. Nie musi zapewniać ani uprawnień administratora, ani połączenia zdalnego. Skutki zależą od tego, do czego daje dostęp."], "bullets": []}, {"title": "RAT i legalne narzędzia", "paragraphs": ["Remote Access Trojan jest złośliwym narzędziem potajemnej zdalnej kontroli. Może dostarczać lub wykorzystywać backdoor. Trzeba odróżniać go od legalnego oprogramowania administracyjnego. Napastnik może też nadużyć już obecnych narzędzi — to podejście living off the land. Sama obecność legalnego programu nie dowodzi legalności jego użycia."], "bullets": []}, {"title": "Boty i botnety", "paragraphs": ["Bot automatyzuje czynności i nie zawsze jest złośliwy. Przejęte urządzenie, czasem nazywane zombie, może wykonywać polecenia operatora i czekać w uśpieniu. Botnet to sieć takich urządzeń wykorzystywana m.in. do DDoS, spamu, phishingu i rozsyłania malware. Brak widocznej aktywności nie oznacza braku przejęcia.", "Uprawniony audyt opiera się na zgodzie. Nazwanie operacji „testem” nie legalizuje korzystania z cudzych zainfekowanych urządzeń."], "bullets": []}], "remember": "Backdoor opisuje obejście zabezpieczeń, RAT zdalną kontrolę, a botnet wiele sterowanych urządzeń.", "example": "Przykład dydaktyczny: Laptop czeka na polecenie i dopiero nocą wysyła spam. Użytkowniczka może nie zauważać działania, choć urządzenie należy do botnetu.", "pitfalls": "Nie myl RAT z każdym narzędziem pulpitu zdalnego ani bota z malware.", "quiz": [{"q": "Czy backdoor zawsze daje prawa administratora?", "options": ["Tak", "Nie", "Tylko w telefonach"], "answer": 1, "why": "Backdoor omija zabezpieczenia, ale poziom uprawnień zależy od konkretnej sytuacji."}, {"q": "Napastnik nadużywa narzędzi już zainstalowanych w systemie. To przykład:", "options": ["Living off the land", "Wyłącznie bloatware", "Solonego hasha"], "answer": 0, "why": "To wykorzystanie dostępnych legalnych narzędzi do szkodliwych celów."}, {"q": "Przejęte urządzenie czeka bezczynnie na polecenia. Czy może należeć do botnetu?", "options": ["Nie", "Tylko gdy wyświetla reklamę", "Tak"], "answer": 2, "why": "Urządzenie zombie może pozostawać uśpione do otrzymania zadania."}], "visual": null}, {"id": "w4-skutki", "track": 4, "title": "Okup, kopanie kryptowalut i objawy infekcji", "subtitle": "Oceń skutek i sprawdź dowody", "slides": "Wykład 4 · strony PDF 11–12 (numer slajdu = strona PDF − 1)", "icon": "🛡️", "sections": [{"title": "Ransomware i presja na ofiarę", "paragraphs": ["Ransomware szyfruje dane lub blokuje dostęp i żąda okupu. Napastnik może wcześniej wykraść dane oraz grozić ich publikacją. Wymuszenie oparte wyłącznie na wycieku nie wymaga szyfrowania. Rozprzestrzenianie może korzystać ze skradzionych kont i narzędzi administracyjnych. Zapłata nie gwarantuje odzyskania danych."], "bullets": []}, {"title": "Cryptojacking i bomba logiczna", "paragraphs": ["Cryptojacking to nieautoryzowane wykorzystanie CPU lub GPU do wydobywania kryptowalut: zwiększa koszty, obciąża sprzęt i ogranicza dostępność. Bomba logiczna uruchamia szkodliwy kod po spełnieniu warunku, np. konkretnej daty albo wyłączeniu konta pracownika. Nie musi zadziałać od razu po instalacji."], "bullets": []}, {"title": "Objawy wymagają weryfikacji", "paragraphs": ["Przekierowania, nowe paski narzędzi, reklamy, wysoka aktywność dysku czy utrata dostępu są sygnałami do sprawdzenia. Mają też inne przyczyny: skan antywirusowy może obciążać CPU, awaria blokować usługę, a VPN zmieniać lokalizację logowania.", "Fałszywy komunikat antywirusa może straszyć infekcją, żeby wymusić instalację lub płatność — to scareware. Nie każdy taki komunikat jest ransomware. Najpierw ustal, co rzeczywiście zostało zablokowane i jakie zdarzenia towarzyszą ostrzeżeniu."], "bullets": []}], "remember": "Objaw to wskazówka, a nie diagnoza. Ransomware, cryptojacking i bomba logiczna opisują różne mechanizmy.", "example": "Przykład dydaktyczny: Wentylator pracuje głośno podczas zaplanowanego skanu. Wysokie CPU samo w sobie nie dowodzi nielegalnego kopania kryptowalut.", "pitfalls": "Zapłata okupu nie daje gwarancji. Nie utożsamiaj każdej groźby na ekranie z zaszyfrowaniem plików.", "quiz": [{"q": "Co jest celem cryptojackingu?", "options": ["Nieautoryzowane wydobywanie kryptowalut", "Sprawdzanie certyfikatu", "Tworzenie soli"], "answer": 0, "why": "Wykorzystuje zasoby ofiary bez jej zgody."}, {"q": "Kod uruchamia się po usunięciu konta pracownika. To:", "options": ["Web beacon", "Bomba logiczna", "Zwykły cookie"], "answer": 1, "why": "Wyzwalaczem jest warunek, niekoniecznie data."}, {"q": "Wysokie użycie CPU oznacza:", "options": ["Zawsze malware", "Zawsze ransomware", "Potrzebę sprawdzenia przyczyny"], "answer": 2, "why": "Obciążenie może pochodzić także od legalnych procesów."}], "visual": null}, {"id": "w4-fizyczne", "track": 4, "title": "Ataki fizyczne, rozpoznanie i wyciek", "subtitle": "Od drzwi budynku do danych organizacji", "slides": "Wykład 4 · strony PDF 13–14 (numer slajdu = strona PDF − 1)", "icon": "🛡️", "sections": [{"title": "Fizyczne zależności bezpieczeństwa", "paragraphs": ["Atak może polegać na sforsowaniu bariery albo sabotażu zasilania, światłowodu i chłodzenia. Usługa może być niedostępna bez przełamania jej hasła: infrastruktura fizyczna jest częścią bezpieczeństwa."], "bullets": []}, {"title": "Odczyt identyfikatora nie oznacza pełnego klonu", "paragraphs": ["Pasywny tag RFID odpowiada na odczyt czytnika. Trzeba oddzielić nieautoryzowany odczyt, skopiowanie identyfikatora i wykonanie działającej kopii karty. Słabe rozwiązania oparte na stałym identyfikatorze łatwiej skopiować niż system z dodatkową weryfikacją.", "NFC działa na krótki dystans. W płatnościach EMV występują dynamiczne dane kryptograficzne transakcji, więc sam odczyt nie tworzy działającego klonu karty płatniczej. Pilot do bramy może używać zupełnie innych pasm i protokołów niż NFC."], "bullets": []}, {"title": "Rozpoznanie i eksfiltracja", "paragraphs": ["Rozpoznanie to zbieranie informacji o organizacji: domenach, usługach, pracownikach i otoczeniu, również np. z wyrzuconych dokumentów. Może trwać długo, ale automatyczny atak oportunistyczny nie zawsze potrzebuje osobnego długiego rozpoznania. Eksfiltracja to wyprowadzenie danych po uzyskaniu do nich dostępu. Dane mogą posłużyć do sprzedaży, publikacji lub wymuszenia. DoS dotyczy dostępności, nie jest synonimem kradzieży danych."], "bullets": []}], "remember": "Odczyt, kopiowanie identyfikatora i pełne sklonowanie uprawnień to trzy różne rzeczy.", "example": "Przykład dydaktyczny: Przerwanie kabla pozbawia biuro dostępu do usługi. Nie trzeba do tego znać haseł jej użytkowników.", "pitfalls": "Nie przypisuj NFC wszystkich pilotów ani nie zakładaj, że odczyt karty płatniczej wystarcza do jej sklonowania.", "quiz": [{"q": "Przecięcie światłowodu przede wszystkim narusza:", "options": ["Dostępność", "Wyłącznie niezaprzeczalność", "Zawsze poufność"], "answer": 0, "why": "Sabotaż infrastruktury może zatrzymać usługę."}, {"q": "Odczyt identyfikatora karty oznacza:", "options": ["Zawsze pełny klon płatniczy", "Nie musi umożliwiać wykonania działającej kopii", "Automatyczne poznanie PIN"], "answer": 1, "why": "Działająca kopia zależy od mechanizmu uwierzytelniania, np. dynamicznych danych EMV."}, {"q": "Wyprowadzenie skopiowanych danych poza organizację to:", "options": ["Samo rozpoznanie", "DoS", "Eksfiltracja"], "answer": 2, "why": "Eksfiltracja wymaga dostępu do danych i polega na ich wyprowadzeniu."}], "visual": null}, {"id": "w4-sieci", "track": 4, "title": "On-path i fałszywe Wi-Fi", "subtitle": "Pozycja w sieci nie oznacza złamania TLS", "slides": "Wykład 4 · strony PDF 15–16 (numer slajdu = strona PDF − 1)", "icon": "🛡️", "sections": [{"title": "Co daje pozycja pośrednika?", "paragraphs": ["Atak on-path oznacza znalezienie się na drodze komunikacji, aby przechwytywać, przekazywać lub modyfikować ruch. Analizator pakietów, taki jak Wireshark, pozwala badać dostępne pakiety, ale sam nie przekierowuje do siebie ruchu i nie łamie szyfrowania TLS."], "bullets": []}, {"title": "ARP poisoning", "paragraphs": ["ARP wiąże lokalny adres IP z adresem MAC. Zatrucie pamięci ARP polega na wprowadzeniu fałszywych skojarzeń, np. podszyciu się pod bramę. To może zmienić drogę ruchu w sieci lokalnej. Poprawnie zweryfikowany HTTPS/TLS nadal chroni treść: odczyt hasła wymaga dodatkowych warunków, np. braku szyfrowania, problemu z zaufaniem do certyfikatu albo przejętego urządzenia końcowego."], "bullets": []}, {"title": "Rogue AP a evil twin", "paragraphs": ["Rogue AP to nieautoryzowany punkt dostępowy; nie musi podszywać się pod konkretną sieć. Evil twin imituje zaufany punkt, np. nazwą SSID. Jednak taka sama nazwa nie gwarantuje automatycznego połączenia: znaczenie mają ustawienia klienta i uwierzytelnianie.", "Fałszywa sieć może zapewniać działający internet i wykorzystywać to zaufanie do phishingu. Operator może obserwować metadane, ale samo Wi-Fi nie daje treści poprawnie chronionej przez TLS. Nie należy ignorować ostrzeżeń o certyfikatach."], "bullets": []}], "remember": "Kontrola drogi komunikacji i odczyt zaszyfrowanej treści to różne możliwości.", "example": "Przykład dydaktyczny: Sieć z nazwą hotelu ma internet, ale prowadzi do podejrzanego formularza logowania. Dostęp do internetu nie dowodzi autentyczności punktu.", "pitfalls": "Wireshark nie łamie sam TLS. Evil twin nie wymaga DoS ani nie gwarantuje połączenia urządzenia.", "quiz": [{"q": "Co samodzielnie robi Wireshark?", "options": ["Łamie każdy TLS", "Analizuje dostępne pakiety", "Zawsze staje się bramą"], "answer": 1, "why": "Do analizy trzeba mieć dostęp do ruchu; narzędzie samo go nie przekierowuje ani nie odszyfrowuje poprawnego TLS."}, {"q": "ARP poisoning fałszuje skojarzenia:", "options": ["IP–MAC w sieci lokalnej", "Hasło–sól w bazie", "Nazwisko–PESEL"], "answer": 0, "why": "ARP służy lokalnemu ustalaniu adresów MAC dla IP."}, {"q": "Punkt kopiuje SSID hotelu. Czy urządzenie na pewno się połączy?", "options": ["Tak, zawsze", "Tak, gdy działa internet", "Nie, zależy też od konfiguracji i uwierzytelniania"], "answer": 2, "why": "Sama nazwa sieci nie wystarcza do zagwarantowania połączenia."}], "visual": null}, {"id": "w4-hasla", "track": 4, "title": "Ataki na hasła", "subtitle": "Słownik, brute force, rainbow tables i spraying", "slides": "Wykład 4 · strony PDF 17 (numer slajdu = strona PDF − 1)", "icon": "🛡️", "sections": [{"title": "Różne strategie zgadywania", "paragraphs": ["Atak słownikowy wykorzystuje przygotowaną listę haseł i jej warianty. Dodanie znaku specjalnego do popularnego słowa nie usuwa tego ryzyka. Brute force systematycznie sprawdza kombinacje znaków; długość i przestrzeń możliwych haseł wpływają na koszt."], "bullets": []}, {"title": "Online a offline", "paragraphs": ["Przy próbach online serwer może ograniczać częstotliwość logowania. Przy ataku offline napastnik ma kopię hashy i sprawdza kandydatów bez pytania usługi o każde logowanie. Ochrona magazynu haseł ma więc znaczenie niezależne od ograniczenia prób w formularzu.", "Rainbow tables wykorzystują wcześniej przygotowane zależności dla hashy, zamieniając koszt obliczeń na koszt przygotowania i pamięci. Unikatowa sól ogranicza ponowne użycie takich obliczeń dla wielu haseł. Sól nie jest szyfrowaniem i nie zamienia krótkiego hasła w długie."], "bullets": []}, {"title": "Password spraying i obrona", "paragraphs": ["Spraying sprawdza niewielką liczbę popularnych haseł na wielu kontach. To inny wzorzec niż wiele prób przeciw jednej osobie. Długie, unikatowe hasła, zmiana haseł domyślnych i MFA pomagają ograniczać ryzyko. Sama złożoność zapisu nie gwarantuje odporności."], "bullets": []}], "remember": "Spraying: mało haseł, wiele kont. Offline: sprawdzanie hashy bez logowania do serwera.", "example": "Przykład dydaktyczny: Jedno popularne hasło sprawdzane na stu kontach to spraying, nawet jeśli każde konto widzi tylko jedną próbę.", "pitfalls": "Limit prób online nie zatrzymuje obliczeń na wykradzionej kopii hashy. Popularne słowo z „!” nadal może być w słowniku.", "quiz": [{"q": "Kilka popularnych haseł na wielu kontach to:", "options": ["Password spraying", "Eksfiltracja", "Replay"], "answer": 0, "why": "Spraying rozprasza próby między kontami."}, {"q": "Co ogranicza wykorzystanie wspólnych gotowych obliczeń hashy?", "options": ["Sama nazwa konta", "Unikatowa sól", "Ukrycie formularza"], "answer": 1, "why": "Sól powoduje, że te same hasła nie są przetwarzane identycznie we wszystkich rekordach."}, {"q": "Dlaczego limit logowań nie wystarcza przy wykradzionych hashach?", "options": ["Ponieważ sól zawsze jest tajna", "Bo MFA nigdy nie działa", "Sprawdzanie kandydatów odbywa się offline"], "answer": 2, "why": "Atakujący nie musi pytać serwera o każdą próbę."}], "visual": null}, {"id": "w4-aplikacje-sesje", "track": 4, "title": "Luki aplikacji i przejęcie sesji", "subtitle": "RCE, eskalacja uprawnień oraz replay", "slides": "Wykład 4 · strony PDF 18–20 (numer slajdu = strona PDF − 1)", "icon": "🛡️", "sections": [{"title": "Wykonanie kodu a uprawnienia", "paragraphs": ["Luka może wynikać z kodu, architektury lub projektu aplikacji czy systemu operacyjnego. Dowolne wykonanie kodu oznacza możliwość uruchomienia kodu w kontekście podatnego procesu. RCE wskazuje, że można to wywołać zdalnie. Nie oznacza automatycznie administratora.", "Eskalacja uprawnień to uzyskanie dostępu większego niż przyznany. Nie zawsze polega na uruchamianiu własnego kodu. Atakujący może potrzebować osobnej luki, aby z konta procesu przejść do uprawnień administratora."], "bullets": []}, {"title": "Dlaczego token ma znaczenie?", "paragraphs": ["HTTP jest bezstanowy, lecz aplikacja może utrzymywać sesję przez identyfikator, np. w cookie. Po zalogowaniu ten identyfikator pomaga rozpoznawać kolejne żądania. Kradzież tokenu może pozwolić udawać zalogowaną osobę bez ponownego wpisywania hasła. Zarówno cookies sesyjne, jak i trwałe mogą zostać skradzione."], "bullets": []}, {"title": "Replay i ograniczanie skutków", "paragraphs": ["Replay to ponowne użycie przechwyconej poprawnej wiadomości lub tokenu. Nie ogranicza się do cookies. TLS chroni transmisję, wygasanie i unieważnianie ograniczają czas użycia tokenu, a jednorazowe wyzwania lub kontrola sekwencji pomagają wykrywać powtórzenia.", "Tryb prywatny ogranicza lokalne ślady, ale nie chroni sam w sobie aktywnej sesji przed przejęciem. MFA utrudnia logowanie napastnikowi, lecz nie musi zatrzymać użycia skradzionego tokenu już uwierzytelnionej sesji."], "bullets": []}], "remember": "RCE nie znaczy „administrator”. Znajomość hasła nie jest konieczna, jeśli napastnik przejmie ważną sesję.", "example": "Przykład dydaktyczny: Aplikacja przyjmuje skradziony ważny token. Napastnik korzysta z istniejącej sesji, więc nie musi ponownie przechodzić ekranu MFA.", "pitfalls": "Nie traktuj trybu incognito ani MFA jako pełnej ochrony przed kradzieżą sesji.", "quiz": [{"q": "RCE w procesie o małych uprawnieniach daje automatycznie:", "options": ["Administratora", "Wykonanie kodu w kontekście procesu", "Wyłącznie odczyt cookies"], "answer": 1, "why": "Wyższe uprawnienia mogą wymagać kolejnej luki."}, {"q": "Ponowne wysłanie przechwyconej poprawnej wiadomości to:", "options": ["Replay", "Cryptojacking", "Bloatware"], "answer": 0, "why": "Istotą replay jest ponowne użycie poprawnego komunikatu lub tokenu."}, {"q": "Czy tryb prywatny gwarantuje ochronę aktywnej sesji?", "options": ["Tak", "Tak, jeżeli hasło jest długie", "Nie"], "answer": 2, "why": "Ogranicza lokalne ślady, ale nie zabezpiecza samodzielnie przed przejęciem tokenu."}], "visual": null}]);
GLOSSARY.push(...[["PUP/PUA", "Potencjalnie niechciane oprogramowanie, np. dołączone dodatki zmieniające ustawienia."], ["Bloatware", "Zbędne lub nadmierne oprogramowanie, często preinstalowane; nie to samo co PUP."], ["Propagacja robaka", "Samodzielne rozprzestrzenianie kopii przez sieć, czasem po początkowym uruchomieniu przez człowieka."], ["Web beacon", "Piksel śledzący: żądanie zasobu pozwalające serwerowi odnotować np. czas i IP."], ["Supercookie", "Ogólne określenie trwałych sposobów identyfikacji poza zwykłymi cookies."], ["Fingerprinting przeglądarki", "Rozpoznawanie na podstawie zestawu cech przeglądarki lub urządzenia."], ["Keylogger sprzętowy", "Urządzenie rejestrujące naciśnięcia klawiszy; keylogger nie musi być programem."], ["Remote Access Trojan", "Złośliwe oprogramowanie umożliwiające potajemną zdalną kontrolę."], ["Living off the land", "Nadużywanie istniejących legalnych narzędzi systemowych lub administracyjnych."], ["Zombie w botnecie", "Przejęte urządzenie wykonujące polecenia operatora, czasem pozostające w uśpieniu."], ["Cryptojacking", "Nieautoryzowane wydobywanie kryptowalut na zasobach ofiary."], ["Bomba logiczna", "Szkodliwy kod uruchamiany po spełnieniu określonego warunku."], ["Scareware", "Straszące komunikaty lub oprogramowanie nakłaniające np. do instalacji albo płatności."], ["Wymuszenie przez wyciek", "Groźba publikacji wykradzionych danych; może wystąpić bez szyfrowania."], ["Eksfiltracja danych", "Wyprowadzenie danych z systemu lub organizacji po uzyskaniu dostępu."], ["Rozpoznanie celu", "Zbieranie informacji o celu, np. usługach, domenach, pracownikach i otoczeniu."], ["Dynamiczne dane EMV", "Dane kryptograficzne związane z transakcją, utrudniające proste sklonowanie płatniczej karty przez odczyt."], ["ARP poisoning", "Wprowadzenie fałszywych skojarzeń IP–MAC do pamięci ARP w sieci lokalnej."], ["Rogue AP", "Nieautoryzowany punkt dostępowy, niekoniecznie podszywający się pod zaufany."], ["Evil twin", "Punkt Wi-Fi imitujący zaufaną sieć, np. przez nazwę SSID."], ["Atak on-path", "Przechwytywanie lub ingerowanie w komunikację z pozycji pośrednika na jej drodze."], ["Password spraying", "Próbowanie niewielu popularnych haseł przeciw wielu kontom."], ["Atak offline na hasła", "Sprawdzanie kandydatów na kopii hashy bez wysyłania każdej próby do usługi."], ["Rainbow tables", "Wcześniej przygotowane zależności dla hashy, przyspieszające odgadywanie kosztem przygotowania i pamięci."], ["RCE", "Zdalnie wywołane wykonanie kodu w kontekście podatnego procesu; nie zawsze z prawami administratora."], ["Eskalacja uprawnień", "Uzyskanie uprawnień większych niż pierwotnie przyznane."], ["Replay", "Ponowne użycie przechwyconej poprawnej wiadomości lub tokenu."], ["Unieważnienie sesji", "Odebranie ważności identyfikatorowi sesji, aby nie był dalej akceptowany."]]);
LECTURE_MULTI.push(...[{"id": "lecture-multi-w4-malware", "track": 4, "lesson": "w4-malware", "lessonTitle": "Malware: wirus, robak i trojan", "q": "Wybierz poprawne pary.", "options": ["Wirus — replikuje się z nośnikiem", "Robak — automatyczna propagacja", "Trojan — zawsze nie działa zgodnie z obietnicą", "Bloatware — zawsze ransomware"], "answers": [0, 1], "why": "Wirus i robak różnią się sposobem propagacji. Trojan może działać zgodnie z obietnicą, a bloatware nie oznacza wymuszania okupu."}, {"id": "lecture-multi-w4-sledzenie", "track": 4, "lesson": "w4-sledzenie", "lessonTitle": "Śledzenie, spyware i keyloggery", "q": "Które stwierdzenia są poprawne?", "options": ["Keylogger może być sprzętowy", "Każdy piksel jest wirusem", "Spyware może wykonywać zrzuty ekranu", "Cookie zawsze mieści całą historię"], "answers": [0, 2], "why": "Keyloggery mają różne postacie, spyware może rejestrować ekran; śledzenie nie jest automatycznie infekcją."}, {"id": "lecture-multi-w4-zdalna-kontrola", "track": 4, "lesson": "w4-zdalna-kontrola", "lessonTitle": "Backdoor, RAT i botnet", "q": "Wybierz poprawne opisy.", "options": ["Backdoor może ominąć uwierzytelnianie", "Każdy bot jest malware", "Botnet może wysyłać spam", "RAT zawsze oznacza legalny pulpit zdalny"], "answers": [0, 2], "why": "Backdoor omija normalne zabezpieczenia. Boty bywają legalne, a złośliwy RAT służy potajemnej kontroli."}, {"id": "lecture-multi-w4-skutki", "track": 4, "lesson": "w4-skutki", "lessonTitle": "Okup, kopanie kryptowalut i objawy infekcji", "q": "Które zdania są poprawne?", "options": ["Ransomware może łączyć szyfrowanie z kradzieżą danych", "Zapłata zawsze odzyskuje dane", "Legalny skan może obciążać CPU", "Każde scareware szyfruje dysk"], "answers": [0, 2], "why": "Atak może obejmować wyciek, a objawy mają też legalne przyczyny. Okup nie gwarantuje odzyskania plików."}, {"id": "lecture-multi-w4-fizyczne", "track": 4, "lesson": "w4-fizyczne", "lessonTitle": "Ataki fizyczne, rozpoznanie i wyciek", "q": "Wybierz poprawne stwierdzenia.", "options": ["Sabotaż chłodzenia może zagrozić dostępności", "Każdy pilot bramy to NFC", "Rozpoznanie może korzystać z publicznych danych", "Odczyt RFID zawsze daje pełny klon karty"], "answers": [0, 2], "why": "Infrastruktura i informacje publiczne mają znaczenie. Rodzaj protokołu i mechanizm weryfikacji karty zmieniają możliwości ataku."}, {"id": "lecture-multi-w4-sieci", "track": 4, "lesson": "w4-sieci", "lessonTitle": "On-path i fałszywe Wi-Fi", "q": "Które stwierdzenia są poprawne?", "options": ["Evil twin może zapewniać internet", "On-path zawsze ujawnia hasła HTTPS", "Wireshark jest analizatorem pakietów", "Każdy rogue AP musi kopiować SSID"], "answers": [0, 2], "why": "Działający internet nie dowodzi zaufania; poprawny TLS nadal chroni treść. Rogue AP nie musi imitować innej sieci."}, {"id": "lecture-multi-w4-hasla", "track": 4, "lesson": "w4-hasla", "lessonTitle": "Ataki na hasła", "q": "Wybierz poprawne pary.", "options": ["Spraying — wiele kont, mało haseł", "Brute force — systematyczne kombinacje", "Offline — wymaga logowania do serwera przy każdej próbie", "Sól — gwarancja siły dowolnego hasła"], "answers": [0, 1], "why": "Offline nie korzysta z formularza logowania dla każdej próby, a sól nie zastępuje silnego hasła."}, {"id": "lecture-multi-w4-aplikacje-sesje", "track": 4, "lesson": "w4-aplikacje-sesje", "lessonTitle": "Luki aplikacji i przejęcie sesji", "q": "Które stwierdzenia są poprawne?", "options": ["MFA nie musi zatrzymać użycia skradzionej sesji", "RCE zawsze daje administratora", "Wygasanie tokenów ogranicza czas nadużycia", "Replay dotyczy wyłącznie cookies"], "answers": [0, 2], "why": "Sesja może omijać kolejne logowanie; czas ważności ogranicza jej wykorzystanie. RCE i replay mają szersze, odrębne znaczenia."}].filter(q=>!LECTURE_MULTI.some(old=>old.id===q.id)));
const TOTAL = LESSONS.length;
const STATE_KEY = 'cyber-od-zera-v1';
let saved = {done:[],flashKnown:[],examBest:0,examCount:0,quizScores:{}};

let view='home', lessonId=null, trackFilter=0, query='', flashIndex=0, flashReveal=false, demoStep=0,examQs=[],examIndex=0,examAnswers=[],examType='all',quizAnswers={},quizShown={};
const $=id=>document.getElementById(id);
function h(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function save(){queueMicrotask(()=>cloudSave());}
function percent(){return Math.round((saved.done.length/TOTAL)*100)}
function toast(m){const t=$('toast');t.textContent=m;t.classList.add('show');clearTimeout(toast._t);toast._t=setTimeout(()=>t.classList.remove('show'),3000)}
function goto(page,id=null){view=page;lessonId=id;query='';$('globalSearch').value='';demoStep=0;closeSidebar();render();window.scrollTo({top:0,behavior:'smooth'});}
function closeSidebar(){$('sidebar').classList.remove('open');$('overlay').classList.remove('show')}
function nav(){for(const track of [1,2,3,4]){$('navTrack'+track).innerHTML=LESSONS.filter(l=>l.track===track).map(l=>`<button class="lesson-nav ${lessonId===l.id&&view==='lesson'?'active':''} ${saved.done.includes(l.id)?'done':''}" data-lesson="${l.id}"><span class="mini-ico">${l.icon}</span><span>${h(l.title)}</span></button>`).join('');}document.querySelectorAll('.menu-btn[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===view || (view==='lesson'&&b.dataset.page==='lessons')));$('topStatus').textContent=percent()===100?'Cały materiał ukończony! 🏆':`${percent()}% materiału za Tobą`;}
function lessonCard(l){return `<button class="lesson-card" data-lesson="${l.id}"><div class="tag-row"><span class="lesson-icon">${l.icon}</span><span class="tag ${saved.done.includes(l.id)?'green':'grey'}">${saved.done.includes(l.id)?'✓ Ukończona':'Do nauki'}</span></div><h3>${h(l.title)}</h3><p>${h(l.subtitle)}</p><div class="tag-row"><span class="tag">WYKŁAD ${l.track}</span><span class="mini muted">Otwórz →</span></div></button>`}
function homepage(){const next=LESSONS.find(l=>!saved.done.includes(l.id))||LESSONS[0];return `<section class="hero"><div><div class="hero-tag">✦ Kurs stworzony na podstawie Twoich wykładów</div><h1>Bezpieczeństwo IT<br>nareszcie po ludzku.</h1><p>Zero wiedzy na wejściu? Idealnie. Tłumaczymy wszystko od początku: proste historie, schematy, fiszki i pytania jak na zejściówce.</p><button class="primary-btn white" data-lesson="${next.id}">${saved.done.length?'Kontynuuj naukę':'Zacznij pierwszą lekcję'} →</button></div><div class="hero-illustration"><div class="hero-orb"><span>🔐</span></div><div class="hero-small one">✨</div><div class="hero-small two">🗝️</div></div></section>
<div class="stat-grid"><div class="stat"><div class="sm">Ukończone lekcje</div><div class="num">${saved.done.length}<span class="muted"> / ${TOTAL}</span></div><div class="meter"><div style="width:${percent()}%"></div></div></div><div class="stat"><div class="sm">Opanowane fiszki</div><div class="num">${saved.flashKnown.length}<span class="muted"> / ${GLOSSARY.length}</span></div><div class="help">Każda opanowana fiszka to jedno pojęcie</div></div><div class="stat"><div class="sm">Najlepszy wynik testu</div><div class="num">${saved.examBest}<span class="muted">%</span></div><div class="help">Twoje testy: ${saved.examCount}</div></div></div>
<div class="section-heading"><h2>Twoje cztery wykłady</h2><small>Wybierz blok tematyczny</small></div><div class="track-grid"><div class="track-card"><div class="ico">🛡️</div><h3>Wykład 1 — Podstawy bezpieczeństwa</h3><p>CIA, NIST, kontrola dostępu, kategorie zabezpieczeń, role i należyta staranność.</p><div class="foot"><span>${LESSONS.filter(l=>l.track===1).length} lekcji</span><button class="secondary-btn" data-filter="1">Przejdź do lekcji →</button></div></div><div class="track-card"><div class="ico">🔐</div><h3>Wykład 2 — Kryptografia</h3><p>Klucze, szyfrowanie, hash, podpisy cyfrowe, certyfikaty i blockchain.</p><div class="foot"><span>${LESSONS.filter(l=>l.track===2).length} lekcji</span><button class="secondary-btn" data-filter="2">Przejdź do lekcji →</button></div></div><div class="track-card"><div class="ico">🎭</div><h3>Wykład 3 — Aktorzy zagrożeń</h3><p>Motywacje, APT, insiderzy, wektory ataku, socjotechnika i phishing.</p><div class="foot"><span>8 lekcji</span><button class="secondary-btn" data-filter="3">Przejdź do lekcji →</button></div></div><div class="track-card"><div class="ico">🦠</div><h3>Wykład 4 — Malware i techniki ataków</h3><p>Wirusy, ransomware, Wi-Fi, ataki na hasła, RCE i przejęcie sesji.</p><div class="foot"><span>8 lekcji</span><button class="secondary-btn" data-filter="4">Przejdź do lekcji →</button></div></div></div>
<div class="section-heading"><h2>Co dalej?</h2><small>Twoja kolejna lekcja</small></div><div class="lesson-grid">${[next,...LESSONS.filter(l=>l.id!==next.id&&!saved.done.includes(l.id)).slice(0,2)].map(lessonCard).join('')}</div><div class="section-heading"><h2>Jak działa aplikacja?</h2></div><div class="more-grid"><div class="source-card"><strong>📚 ${TOTAL} lekcji + weryfikacja wiedzy</strong><p>Każde zagadnienie opisane prosto, z przykładami i pytaniami sprawdzającymi.</p></div><div class="source-card"><strong>🃏 Fiszki i próbny test</strong><p>Powtarzaj definicje i rozwiązuj losowo dobrane pytania z czterech wykładów.</p></div></div><p class="footer-note">Źródło: „Bezpieczeństwo IT — Wykład 1” (53 strony) , „Bezpieczeństwo IT — Wykład 2” (20 stron) oraz „Bezpieczeństwo IT — Wykład 3” (26 stron PDF) oraz „Bezpieczeństwo IT — Wykład 4” (20 stron PDF), dr inż. Marcin Grabarczyk, semestr zimowy 2026/2027. Proste analogie, ćwiczenia i dodatkowe objaśnienia są materiałem edukacyjnym do tych slajdów.</p>`}
function lessonspage(){let ls=LESSONS.filter(l=>!trackFilter||l.track===trackFilter);return `<div class="eyebrow">Twój program nauki</div><h1 class="page-title">Lekcje, które mają sens.</h1><p class="lede">Wybieraj temat w dowolnej kolejności. Najlepiej zacznij od pierwszego wykładu — pojęcia są ułożone od łatwiejszych do trudniejszych.</p><div class="track-toggle"><button class="${trackFilter===0?'active':''}" data-filter="0">Wszystkie (${TOTAL})</button><button class="${trackFilter===1?'active':''}" data-filter="1">Wykład 1</button><button class="${trackFilter===2?'active':''}" data-filter="2">Wykład 2</button><button class="${trackFilter===3?'active':''}" data-filter="3">Wykład 3</button><button class="${trackFilter===4?'active':''}" data-filter="4">Wykład 4</button></div><div class="lesson-grid">${ls.map(lessonCard).join('')}</div>`}
function visual(kind){if(!kind)return '';let head={'cia':'Triada CIA: trzy pytania','nist':'Plan działania w cyklu','aaa':'Etapy kontroli dostępu','categories':'Kategorie: kto lub co działa?','types':'Typy: kiedy i po co?','crypto':'Od tekstu jawnego do szyfrogramu','keys':'Klucze publiczny i prywatny — symulacja','hybrid':'Dwa rodzaje kryptografii razem','bits':'Każdy bit podwaja możliwości','hash':'Eksperyment: zmień choć jedną literę','signature':'Dwa zadania, dwa zestawy kluczy','pki':'Kto potwierdza klucz serwera?','data':'Trzy stany tych samych danych','salt':'Dwie osoby, to samo hasło','blockchain':'Powiązane bloki'}[kind]||'Prosty schemat';let out=`<div class="visual"><h4>✦ ${head}</h4>`;
const row=(items)=>`<div class="v-row">${items.map((x,i)=>`${i?'<span class="v-arrow">→</span>':''}<div class="v-pill">${x}</div>`).join('')}</div>`;
if(kind==='cia')out+=row(['🔒 C<small>Poufność</small>','📝 I<small>Integralność</small>','📶 A<small>Dostępność</small>'])+'<p class="visual-desc">Czytać tylko uprawnionym • nie zmieniać bez zgody • udostępniać, kiedy trzeba.</p>';
else if(kind==='nist')out+=row(['Identify','Protect','Detect'])+'<div style="height:8px"></div>'+row(['Respond','Recover','Govern*'])+'<p class="visual-desc">* Govern — funkcja dodana w NIST CSF 2.0 i obejmująca nadzór nad pozostałymi.</p>';
else if(kind==='aaa')out+=row(['👤 Login<small>Identyfikacja</small>','🔑 Hasło<small>Uwierzytelnianie</small>','🎫 Prawa<small>Autoryzacja</small>'])+'<p class="visual-desc">📋 Accounting = zapisywanie działań w logach. Skrót AAA obejmuje 3 ostatnie etapy.</p>';
else if(kind==='categories')out+=row(['📑 Reguły<small>Zarządcza</small>','🧍 Człowiek<small>Operacyjna</small>'])+'<div style="height:8px"></div>'+row(['💻 Program<small>Techniczna</small>','🚪 Bariera<small>Fizyczna</small>']);
else if(kind==='types')out+=row(['PRZED<small>dyrektywne • odstraszające • prewencyjne</small>','W TRAKCIE<small>wykrywające</small>','PO<small>korygujące • odtworzeniowe</small>'])+'<p class="visual-desc">Kompensujące zastępują docelowe zabezpieczenie na dowolnym etapie.</p>';
else if(kind==='crypto')out+=row(['„Cześć”<small>Tekst jawny</small>','🔑 + szyfr<small>Encryption</small>','7#x!2<small>Szyfrogram*</small>'])+'<p class="visual-desc">* Znaki to tylko ilustracja, nie wynik prawdziwego szyfru.</p>';
else if(kind==='keys'){
let steps=[['1. Ty tworzysz parę kluczy','Twój publiczny klucz można udostępnić, Twój prywatny pozostaje u Ciebie.'],['2. Ania bierze Twój publiczny','Ania szyfruje nim wiadomość specjalnie dla Ciebie.'],['3. Wiadomość podróżuje przez sieć','Ktoś może przechwycić szyfrogram, ale nie powinien odczytać treści.'],['4. Odszyfrowujesz prywatnym','Dopiero pasujący prywatny klucz pozwala odczytać wiadomość.']];out+=`<div class="pill-switch">${steps.map((s,i)=>`<button class="${demoStep===i?'active':''}" data-demo="${i}">Krok ${i+1}</button>`).join('')}</div><div class="v-demo"><div class="big">${steps[demoStep][0]}</div><div style="margin:7px 0">${steps[demoStep][1]}</div><div style="font-size:30px;margin-top:12px;text-align:center">${['🔐 → 🗝️','👩 → 🔒','📨 → 🌐','🗝️ → 💬'][demoStep]}</div></div><p class="visual-desc">Klikaj kroki, aby przejść cały proces. To analogia, nie rzeczywiste generowanie kluczy.</p>`;
}
else if(kind==='hybrid')out+=row(['📦 Duży plik<small>Symetrycznie</small>','🗝️ Mały sekret<small>Asymetrycznie*</small>'])+'<p class="visual-desc">* W modelu ze slajdu; nowoczesny TLS często uzgadnia sekret przez wymianę kluczy.</p>';
else if(kind==='bits')out+=`<div class="v-row" style="justify-content:flex-start;gap:6px;margin-bottom:12px">${[0,1,1,0,1,0,0,1].map(n=>`<span class="bit-square">${n}</span>`).join('')}</div><div class="v-demo">1 bit = 2 możliwości • 2 bity = 4 • 3 bity = 8 • 8 bitów = 256.</div>`;
else if(kind==='hash')out+=`<label class="mini muted" for="hashDemo">Napisz dowolny tekst (to demonstracyjny odcisk, nie SHA-256):</label><input id="hashDemo" class="hash-input" value="Przelej 100 zł" /><div class="hash-out" id="hashResult"></div><p class="visual-desc">Zmień np. „100” na „900”. Wynik się zmieni. To uproszczona symulacja koncepcji hasha, a nie algorytm kryptograficzny.</p>`;
else if(kind==='signature')out+=row(['✍️ Prywatny nadawcy<small>Tworzy podpis</small>','✅ Publiczny nadawcy<small>Weryfikuje</small>']);
else if(kind==='pki')out+=row(['🏛️ CA<small>Wystawia certyfikat</small>','📜 Serwer<small>Przedstawia certyfikat</small>','🌐 Przeglądarka<small>Sprawdza</small>']);
else if(kind==='data')out+=row(['💾 Na dysku<small>At rest</small>','📨 Wysyłane<small>In transit</small>','🧠 W RAM<small>In use</small>']);
else if(kind==='salt')out+=row(['kot123 + sól A<small>Hash A</small>','kot123 + sól B<small>Hash B</small>'])+'<p class="visual-desc">Sole sprawiają, że identyczne hasła nie muszą mieć takich samych wyników.</p>';
else if(kind==='blockchain')out+=row(['Blok 1<small>hash 1</small>','Blok 2<small>hash 1 + 2</small>','Blok 3<small>hash 2 + 3</small>'])+'<p class="visual-desc">Uproszczony łańcuch powiązań — zmiana wcześniejszego bloku zaburza późniejsze.</p>';
return out+'</div>'}
function lessonpage(){const l=LESSONS.find(x=>x.id===lessonId);if(!l)return homepage();let idx=LESSONS.findIndex(x=>x.id===l.id);return `<button class="back-link" data-page="lessons">← Wszystkie lekcje</button><div class="article-head"><div class="article-icon">${l.icon}</div><div><div class="eyebrow">Wykład ${l.track} · Lekcja ${LESSONS.filter(x=>x.track===l.track).findIndex(x=>x.id===l.id)+1}</div><h1>${h(l.title)}</h1><p>${h(l.subtitle)}</p><div class="sourcefoot">Na podstawie: ${h(l.slides)}</div></div></div><div class="article-actions"><button class="${saved.done.includes(l.id)?'secondary-btn':'primary-btn'}" id="markDone">${saved.done.includes(l.id)?'✓ Lekcja ukończona — cofnij':'✓ Oznacz jako opanowaną'}</button><button class="ghost-btn" id="readLesson">🔊 Odsłuchaj</button><button class="ghost-btn" id="printLesson">🖨️ Drukuj / zapisz PDF</button></div><div class="two-col"><div><div class="paper">${visual(l.visual)}${l.sections.map((s,i)=>`<section class="unit-section"><div class="section-inline-label">Krok ${i+1}</div><h3>${s.title}</h3>${s.paragraphs.map(p=>`<p>${p}</p>`).join('')}${s.bullets&&s.bullets.length?`<ul>${s.bullets.map(b=>`<li>${b}</li>`).join('')}</ul>`:''}</section>`).join('')}</div><div class="quiz-card" id="lessonQuiz"><div class="quiz-eyebrow">Zadania jak na zejściówce</div><h3>Sprawdź, czy naprawdę to rozumiesz</h3><p class="mini muted">Odpowiedz na dwa pytania. Po odpowiedzi zobaczysz wyjaśnienie, nie tylko „dobrze/źle”.</p>${l.quiz.map((q,i)=>quizFragment(q,`${l.id}-${i}`,i+1)).join('')}</div><div class="bottom-nav"><button class="ghost-btn" ${idx===0?'disabled':''} ${idx>0?`data-lesson="${LESSONS[idx-1].id}"`:''}>← Poprzednia</button><button class="primary-btn" ${idx===TOTAL-1?'data-page="exam"':`data-lesson="${LESSONS[idx+1].id}"`}>${idx===TOTAL-1?'Przejdź do testu':'Następna lekcja →'}</button></div></div><aside class="rail"><div class="hint"><div class="hint-title">💡 Zapamiętaj</div><p>${h(l.remember)}</p></div><div class="hint example"><div class="hint-title">🌷 Przykład z życia</div><p>${h(l.example)}</p></div><div class="hint warn"><div class="hint-title">⚠️ Częsta pomyłka</div><p>${h(l.pitfalls)}</p></div></aside></div>`}
function quizFragment(q,id,no){const ans=quizAnswers[id],shown=quizShown[id];return `<div style="margin-top:19px;padding-top:18px;border-top:1px solid var(--line)"><div class="mini muted" style="font-weight:700;margin-bottom:5px">PYTANIE ${no}</div><div style="font-weight:750;font-size:14px;line-height:1.5">${h(q.q)}</div>${q.options.map((s,j)=>`<button class="option ${ans===j?'selected':''} ${shown&&correctChoices(q).includes(j)?'correct':''} ${shown&&ans===j&&ans!==q.answer?'wrong':''}" ${shown?'disabled':''} data-mini-answer="${id}" data-answer-index="${j}"><span class="bullet">${String.fromCharCode(65+j)}</span>${h(s)}</button>`).join('')}${shown?`<div class="quiz-answer"><strong>${ans===q.answer?'✅ Super, dobrze!':'🌻 Poprawna odpowiedź: '+h(q.options[q.answer])}</strong><div>${h(q.why)}</div></div>`:`<button class="secondary-btn" data-mini-check="${id}" ${ans===undefined?'disabled':''}>Sprawdź odpowiedź</button>`}</div>`}
function flashpage(){const term=GLOSSARY[flashIndex];const known=saved.flashKnown.includes(term[0]);return `<div class="eyebrow">Fiszki · wszystkie ważne pojęcia</div><h1 class="page-title">Zapamiętasz szybciej.</h1><p class="lede">Kliknij kartę, żeby zobaczyć wyjaśnienie. Oznaczaj pojęcia, które już znasz. Fiszki korzystają ze słownika wykładów.</p><div class="stat-grid" style="max-width:750px"><div class="stat"><div class="sm">Fiszka</div><div class="num">${flashIndex+1}<span class="muted"> / ${GLOSSARY.length}</span></div></div><div class="stat"><div class="sm">Już znam</div><div class="num">${saved.flashKnown.length}</div></div><div class="stat"><div class="sm">Do powtórki</div><div class="num">${GLOSSARY.length-saved.flashKnown.length}</div></div></div><div class="flash-layout"><div class="flashcard" id="flipFlash" role="button" tabindex="0" aria-label="Odwróć fiszkę"><div class="cap">${flashReveal?'ODPOWIEDŹ':'POJĘCIE'}</div>${flashReveal?`<div class="answer">${h(term[1])}</div>`:`<h2>${h(term[0])}</h2>`}<div class="tap">↻ Kliknij, żeby ${flashReveal?'wrócić do pojęcia':'odkryć znaczenie'}</div></div><div class="flash-controls"><button class="ghost-btn" id="flashPrev">← Wstecz</button><button class="${known?'secondary-btn':'primary-btn'}" id="flashKnow">${known?'✓ Znam — cofnij':'✓ Już znam'}</button><button class="ghost-btn" id="flashNext">Dalej →</button></div><div class="flash-controls"><button class="secondary-btn" id="flashUnknown">Losuj nieopanowaną</button><button class="ghost-btn" id="flashRandom">Losowa fiszka 🎲</button></div></div>`}
function glossarypage(){const list=GLOSSARY.filter(x=>(x[0]+' '+x[1]).toLowerCase().includes(query.toLowerCase()));return `<div class="eyebrow">Leksykon · polski i angielski</div><h1 class="page-title">Słownik cyberpojęć.</h1><p class="lede">Nie rozumiesz skrótu? Znajdź go tutaj — każde pojęcie jest wyjaśnione bez skomplikowanego żargonu.</p><div class="section-heading"><h2>${list.length} pojęć</h2><small>Wyszukiwanie działa w górnym polu</small></div><div class="glossary-list">${list.map(x=>`<div class="glossary-item"><strong>${h(x[0])}</strong><p>${h(x[1])}</p></div>`).join('')||'<div class="empty">Brak wyników. Spróbuj wpisać inną frazę.</div>'}</div>`}
function searchpage(){const v=query.toLowerCase();const ls=LESSONS.filter(l=>(l.title+' '+l.subtitle+' '+l.sections.map(s=>s.title+' '+s.paragraphs.join(' ')).join(' ')).toLowerCase().includes(v));const terms=GLOSSARY.filter(x=>(x[0]+' '+x[1]).toLowerCase().includes(v));return `<div class="eyebrow">Wyszukiwanie</div><h1 class="page-title">Wyniki dla „${h(query)}”</h1><p class="lede">Tematy i terminy ze wszystkich czterech wykładów.</p><div class="section-heading"><h2>Lekcje (${ls.length})</h2></div>${ls.length?`<div class="lesson-grid">${ls.map(lessonCard).join('')}</div>`:'<div class="empty">Nie znaleziono lekcji.</div>'}<div class="section-heading"><h2>Pojęcia (${terms.length})</h2></div>${terms.length?`<div class="glossary-list">${terms.slice(0,35).map(x=>`<div class="glossary-item"><strong>${h(x[0])}</strong><p>${h(x[1])}</p></div>`).join('')}</div>`:'<div class="empty">Nie znaleziono pojęć.</div>'}`}
function correctChoices(q){return q.answers||[q.answer]}
function selectedChoices(a){return Array.isArray(a?.answer)?a.answer:Number.isInteger(a?.answer)?[a.answer]:[]}
function isCorrect(q,a){const selected=selectedChoices(a),correct=correctChoices(q);return selected.length===correct.length&&correct.every(i=>selected.includes(i))}
function correctText(q){return correctChoices(q).map(i=>q.options[i]).join('; ')}
function exampage(){return `<div class="eyebrow">Trening wiedzy i Security+</div><h1 class="page-title">Test wiedzy bez stresu.</h1><p class="lede">Domyślny test obejmuje wyłącznie cztery wykłady z kursu. Osobny tryb Security+ SY0-701 wykracza poza te wykłady. Po każdej odpowiedzi dowiesz się, dlaczego jest poprawna lub nie.</p><div class="quiz-config"><label for="examScope">Wybierz zakres</label><select id="examScope"><option value="sec10" ${examType==='sec10'?'selected':''}>Security+ SY0-701 — 10 pytań</option><option value="sec20" ${examType==='sec20'?'selected':''}>Security+ SY0-701 — 20 pytań</option><option value="sec30" ${examType==='sec30'?'selected':''}>Security+ SY0-701 — 30 pytań</option><option value="all" ${examType==='all'?'selected':''}>Wszystkie cztery wykłady — 20 pytań</option><option value="1" ${examType==='1'?'selected':''}>Tylko wykład 1 — 10 pytań</option><option value="2" ${examType==='2'?'selected':''}>Tylko wykład 2 — 10 pytań</option><option value="3" ${examType==='3'?'selected':''}>Tylko wykład 3 — 10 pytań</option><option value="4" ${examType==='4'?'selected':''}>Tylko wykład 4 — 10 pytań</option></select><p class="mini muted">Pytania z wykładów zawierają także wybór wielu odpowiedzi i poprawnych par. Zaznacz wszystkie poprawne: nie podajemy ich liczby. Punkt otrzymujesz tylko za kompletny poprawny zestaw. Security+ (rozszerzenie poza wykłady): 30 autorskich pytań ćwiczeniowych z pięciu obszarów zakresu SY0-701. Nie są to oficjalne pytania egzaminacyjne ani pełna symulacja: bez PBQ, limitu czasu i ważenia domen. Wynik procentowy nie odpowiada punktacji CompTIA. <a href="https://comptiacdn.azureedge.net/webcontent/docs/default-source/exam-objectives/comptia-security-sy0-701-exam-objectives-%286-0%29.pdf" target="_blank" rel="noopener noreferrer">Zakres CompTIA SY0-701</a></p><div class="mini muted">Bez limitu czasu: najpierw naucz się rozumieć. Każdy test miesza kolejność dostępnych pytań.</div><button class="primary-btn" id="startExam">Rozpocznij test →</button></div><div class="section-heading"><h2>Jak się przygotować?</h2></div><div class="more-grid"><div class="source-card"><strong>1. Zrozum każdy przykład</strong><p>W teście scenariuszowym ważniejsze jest dobranie działania niż pamięciowa definicja.</p></div><div class="source-card"><strong>2. Wracaj do błędów</strong><p>Po odpowiedzi czytaj wyjaśnienie. Jeśli coś nadal jest trudne, wróć do odpowiedniej lekcji.</p></div></div>`}
function startExam(){if(examType.startsWith('sec')){examQs=pickSecurityQuestions(Number(examType.slice(3)));examIndex=0;examAnswers=[];view='exam-active';render();window.scrollTo(0,0);return;}const pool=LESSONS.filter(l=>examType==='all'||String(l.track)===examType).flatMap(l=>l.quiz.map(q=>({...q,lesson:l.id,lessonTitle:l.title}))).concat(LECTURE_MULTI.filter(q=>examType==='all'||String(q.track)===examType));for(let i=pool.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[pool[i],pool[j]]=[pool[j],pool[i]];}examQs=pool.slice(0,examType==='all'?20:10);examIndex=0;examAnswers=[];view='exam-active';render();window.scrollTo(0,0)}
function examactive(){const q=examQs[examIndex];if(!q)return exampage();const a=examAnswers[examIndex],shown=!!a?.shown;return `<div class="exam"><div class="eyebrow">Test w toku</div><h1 class="page-title">Dobrze Ci idzie. 💜</h1><div class="exam-counter"><span>Pytanie ${examIndex+1} z ${examQs.length}</span><span>${Math.round(examIndex/examQs.length*100)}% ukończono</span></div><div class="exam-progress"><div style="width:${examIndex/examQs.length*100}%"></div></div><div class="quiz-card" style="margin-top:22px"><div class="quiz-eyebrow">${h(q.lessonTitle)}</div><h3>${h(q.q)}</h3><p class="mini muted">${q.answers?'Zaznacz wszystkie poprawne odpowiedzi.':'Wybierz jedną odpowiedź.'}</p>${q.options.map((s,j)=>`<button class="option ${selectedChoices(a).includes(j)?'selected':''} ${shown&&correctChoices(q).includes(j)?'correct':''} ${shown&&selectedChoices(a).includes(j)&&!correctChoices(q).includes(j)?'wrong':''}" ${shown?'disabled':''} aria-pressed="${selectedChoices(a).includes(j)}" data-exam-answer="${j}"><span class="bullet">${String.fromCharCode(65+j)}</span>${h(s)}</button>`).join('')}${shown?`<div class="quiz-answer"><strong>${isCorrect(q,a)?'✅ Poprawnie!':'🌻 Poprawny zestaw: '+h(correctText(q))}</strong><div>${h(q.why)}</div></div>`:''}<div class="right-actions">${shown?`<button class="primary-btn" id="examNext">${examIndex===examQs.length-1?'Zobacz wynik 🏆':'Następne pytanie →'}</button>`:`<button class="primary-btn" id="examCheck" ${selectedChoices(a).length===0?'disabled':''}>Sprawdź odpowiedź</button>`}</div></div><button class="back-link" id="cancelExam" style="margin-top:18px">← Przerwij test</button></div>`}
function finishExam(){let correct=examQs.filter((q,i)=>isCorrect(q,examAnswers[i])).length;let pct=Math.round(correct/examQs.length*100);saved.examCount++;saved.examBest=Math.max(saved.examBest,pct);save();window.latestScore={correct,pct,total:examQs.length};view='exam-done';render();window.scrollTo(0,0)}
function examdone(){const r=window.latestScore||{correct:0,total:0,pct:0};const wrong=examQs.filter((q,i)=>!isCorrect(q,examAnswers[i]));return `<div class="eyebrow">Test zakończony</div><div class="result"><div style="font-size:48px">${r.pct>=80?'🏆':'🌷'}</div><h1 style="margin:12px 0 2px">${r.pct>=80?'Świetna robota!':'To dobry materiał do powtórki!'}</h1><div class="score">${r.pct}%</div><p class="muted">Poprawne odpowiedzi: ${r.correct} z ${r.total}</p><div class="flash-controls"><button class="primary-btn" id="restartExam">Rozwiąż kolejny test</button><button class="ghost-btn" data-page="lessons">Przejdź do lekcji</button></div></div>${wrong.length?`<div class="section-heading"><h2>Warto powtórzyć (${wrong.length})</h2></div><div class="glossary-list">${wrong.map(q=>`<div class="glossary-item"><strong>${h(q.lessonTitle)}</strong><p>${h(q.q)}<br><b>Odpowiedź:</b> ${h(correctText(q))}</p>${q.id?`<p>${h(q.why)}</p>`:`<button class="back-link" style="margin:8px 0 0" data-lesson="${q.lesson}">Otwórz lekcję →</button>`}</div>`).join('')}</div>`:''}`}
function render(){nav();if(query.trim()&&view!=='lesson'){view='search';nav();$('content').innerHTML=searchpage();return;}const html=view==='home'?homepage():view==='lessons'?lessonspage():view==='lesson'?lessonpage():view==='flash'?flashpage():view==='glossary'?glossarypage():view==='exam'?exampage():view==='exam-active'?examactive():view==='exam-done'?examdone():homepage();$('content').innerHTML=html;if(view==='lesson'&&LESSONS.find(l=>l.id===lessonId)?.visual==='hash')updateHash();}
function updateHash(){const inp=$('hashDemo'),o=$('hashResult');if(!inp||!o)return;let txt=inp.value;let x=2166136261>>>0;for(let ch of new TextEncoder().encode(txt)){x^=ch;x=Math.imul(x,16777619)>>>0;}o.textContent=x.toString(16).padStart(8,'0').toUpperCase()+' (odcisk demonstracyjny, NIE SHA-256)'}
function toggleDone(){if(saved.done.includes(lessonId)){saved.done=saved.done.filter(id=>id!==lessonId);toast('Lekcja przeniesiona do powtórki')}else{saved.done.push(lessonId);toast('Super! Lekcja oznaczona jako opanowana 🎉')}save();render()}
function exportProgress(){const blob=new Blob([JSON.stringify({app:'Cyber od zera',date:new Date().toISOString(),progress:saved},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='moje-postepy-cyber-od-zera.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Eksport postępów gotowy')}
function readLesson(){const l=LESSONS.find(x=>x.id===lessonId);if(!l)return;if(!('speechSynthesis' in window)){toast('Ta przeglądarka nie obsługuje odsłuchu tekstu');return;}if(speechSynthesis.speaking){speechSynthesis.cancel();toast('Zatrzymano odsłuch');return;}let txt=[l.title,...l.sections.flatMap(s=>[s.title,...s.paragraphs.map(p=>p.replace(/<[^>]+>/g,''))])].join('. ');let u=new SpeechSynthesisUtterance(txt);u.lang='pl-PL';u.rate=.93;speechSynthesis.speak(u);toast('Odtwarzam lekcję. Kliknij ponownie, aby zatrzymać.')}
function miniQ(id){const l=LESSONS.find(x=>x.id===lessonId);if(!l)return null;const idx=Number(id.slice(id.lastIndexOf('-')+1));return l.quiz[idx]}
$('openSidebar').addEventListener('click',()=>{$('sidebar').classList.add('open');$('overlay').classList.add('show')});$('overlay').addEventListener('click',closeSidebar);$('goHome').addEventListener('click',()=>goto('home'));
$('globalSearch').addEventListener('input',e=>{query=e.target.value;if(query.trim()){view='search'}else{view='home'}render()});$('globalSearch').addEventListener('keydown',e=>{if(e.key==='Escape'){$('globalSearch').value='';query='';view='home';render()}});
document.addEventListener('input',e=>{if(e.target.id==='hashDemo')updateHash();if(e.target.id==='examScope')examType=e.target.value});
document.addEventListener('click',e=>{const t=e.target.closest('button,[role="button"]');if(!t)return;
if(t.dataset.page){goto(t.dataset.page);return}if(t.dataset.lesson){goto('lesson',t.dataset.lesson);return}if(t.dataset.filter!==undefined){trackFilter=Number(t.dataset.filter);goto('lessons');return}if(t.dataset.demo!==undefined){demoStep=Number(t.dataset.demo);render();return}
if(t.id==='markDone'){toggleDone();return}if(t.id==='printLesson'){window.print();return}if(t.id==='readLesson'){readLesson();return}if(t.id==='exportProgress'){exportProgress();return}
if(t.dataset.miniAnswer!==undefined){quizAnswers[t.dataset.miniAnswer]=Number(t.dataset.answerIndex);render();return}if(t.dataset.miniCheck!==undefined){const id=t.dataset.miniCheck;quizShown[id]=true;const q=miniQ(id),l=LESSONS.find(x=>x.id===lessonId);if(q){const a=quizAnswers[id];const key=lessonId;const stats=saved.quizScores[key]||{correct:0,total:0};stats.total++;if(a===q.answer)stats.correct++;saved.quizScores[key]=stats;save();}render();return}
if(t.id==='flipFlash'){flashReveal=!flashReveal;render();return}if(t.id==='flashPrev'){flashIndex=(flashIndex-1+GLOSSARY.length)%GLOSSARY.length;flashReveal=false;render();return}if(t.id==='flashNext'){flashIndex=(flashIndex+1)%GLOSSARY.length;flashReveal=false;render();return}if(t.id==='flashKnow'){const name=GLOSSARY[flashIndex][0];saved.flashKnown=saved.flashKnown.includes(name)?saved.flashKnown.filter(x=>x!==name):[...saved.flashKnown,name];save();render();return}if(t.id==='flashRandom'){flashIndex=Math.floor(Math.random()*GLOSSARY.length);flashReveal=false;render();return}if(t.id==='flashUnknown'){const ids=GLOSSARY.map((x,i)=>[x[0],i]).filter(x=>!saved.flashKnown.includes(x[0]));if(!ids.length){toast('Znasz wszystkie fiszki! 🏆');return}flashIndex=ids[Math.floor(Math.random()*ids.length)][1];flashReveal=false;render();return}
if(t.id==='startExam'){examType=$('examScope').value;startExam();return}if(t.dataset.examAnswer!==undefined){if(examAnswers[examIndex]?.shown)return;const n=Number(t.dataset.examAnswer),q=examQs[examIndex],old=selectedChoices(examAnswers[examIndex]);examAnswers[examIndex]={answer:q.answers?(old.includes(n)?old.filter(x=>x!==n):[...old,n]):n,shown:false};render();return}if(t.id==='examCheck'){examAnswers[examIndex].shown=true;render();return}if(t.id==='examNext'){if(examIndex===examQs.length-1){finishExam()}else{examIndex++;render();window.scrollTo({top:0,behavior:'smooth'})}return}if(t.id==='cancelExam'){goto('exam');return}if(t.id==='restartExam'){startExam();return}
});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&document.activeElement?.id==='flipFlash'){e.preventDefault();flashReveal=!flashReveal;render();}});

const configURL=import.meta.env.VITE_SUPABASE_URL;
const configKey=import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY;
const configured=!!(configURL&&configKey&&!configURL.includes('YOUR_PROJECT'));
const client=configured?createClient(configURL,configKey,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}}):null;
let user=null,revision=0,lastSnapshot='',dirty=false,saving=false,conflict=false,ready=false,generation=0,authMode='login',recovering=false;
const app=$('courseApp'),account=$('account');
const studentPortal=typeof createStudentPortal==='function'&&client?createStudentPortal(client,{exportCourse:()=>snapshot(),openCourse:()=>{app.hidden=false;account.hidden=true;render();},openProfile:()=>showAccount('profile'),logout:async()=>{await cloudSave();if(dirty)throw Error('Najpierw zapisz oczekujące zmiany kursu.');const {error}=await client.auth.signOut();if(error)throw error;clearAccount();showAccount();}}):null;
function snapshot(){return {version:2,progress:saved,quiz:{answers:quizAnswers,shown:quizShown},flashIndex,exam:{questions:examQs.map(q=>q.id?(q.id.startsWith('lecture-multi-')?{lectureId:q.id}:{securityId:q.id}):{lesson:q.lesson,index:LESSONS.find(l=>l.id===q.lesson)?.quiz.findIndex(x=>x.q===q.q)}),answers:examAnswers,index:examIndex,type:examType,active:view==='exam-active'},history:examHistory};}
let examHistory=[];
function restore(raw={}){
 saved=normalizeProgress(raw.progress||{},LESSONS,GLOSSARY);
 const q=safeAnswers(raw.quiz,LESSONS);quizAnswers=q.answers;quizShown=q.shown;
 flashIndex=Number.isInteger(raw.flashIndex)?Math.max(0,Math.min(raw.flashIndex,GLOSSARY.length-1)):0;flashReveal=false;
 examQs=[];examAnswers=[];examIndex=0;examType='all';
 const ex=raw.exam;
 if(ex&&Array.isArray(ex.questions)&&ex.questions.length<=30){
  examQs=ex.questions.map(r=>{if(r.lectureId)return LECTURE_MULTI.find(q=>q.id===r.lectureId)||null;if(r.securityId)return SECURITY_PLUS.find(q=>q.id===r.securityId)||null;const l=LESSONS.find(x=>x.id===r.lesson),q=l?.quiz[r.index];return q?{...q,lesson:l.id,lessonTitle:l.title}:null;}).filter(Boolean);
  examAnswers=examQs.map((q,i)=>{const a=ex.answers?.[i];if(q.answers&&Array.isArray(a?.answer)&&a.answer.every(n=>Number.isInteger(n)&&n>=0&&n<q.options.length))return {answer:[...new Set(a.answer)],shown:a.shown===true};return Number.isInteger(a?.answer)&&a.answer>=0&&a.answer<q.options.length?{answer:a.answer,shown:a.shown===true}:null;});
  examIndex=Number.isInteger(ex.index)?Math.max(0,Math.min(ex.index,examQs.length-1)):0;
  examType=['all','1','2','3','4','sec10','sec20','sec30'].includes(ex.type)?ex.type:'all';
  if(ex.active&&examQs.length)view='exam-active';
 }
 examHistory=Array.isArray(raw.history)?raw.history.slice(-100):[];
 query='';$('globalSearch').value='';lessonId=null;window.latestScore=null;
}
function status(text){$('syncStatus').textContent=text;}
function message(text){const el=$('accountMessage');if(el)el.textContent=text;}
function showAccount(mode='login',note=''){
 authMode=mode;app.hidden=true;account.hidden=false;
 const profile=mode==='profile', reset=mode==='reset',change=mode==='change',register=mode==='register';
 account.innerHTML=`<div class="brand">✦ STUDEO · BETA</div><h1>${profile?'Twoja przestrzeń nauki':reset?'Odzyskaj dostęp':change?'Ustaw nowe hasło':register?'Zacznij swoją naukę':'Dobrze Cię widzieć.'}</h1><p>${profile?'Twoje postępy są przypisane do Twojego konta.': 'Twoje studia w jednym miejscu: przedmioty, notatki, zadania i powtórki. Bezpłatne Premium w becie dla każdego, bez karty płatniczej.'}</p>
 ${!configured?'<p class="message">Podgląd projektu. Logowanie będzie dostępne po podłączeniu bazy Supabase.</p><button class="primary-btn" id="previewCourse">Obejrzyj kurs</button>':`<form id="accountForm">
 ${profile?`<p>Zalogowana jako: <strong>${h(user?.email)}</strong></p>`:''}
 ${register||profile?`<label for="displayName">Jak mamy Cię nazywać?</label><input id="displayName" name="name" autocomplete="nickname" maxlength="60" value="${h(profile?user?.user_metadata?.display_name||'':'')}" />`:''}
 ${!profile&&!change?'<label for="email">E-mail</label><input id="email" name="email" type="email" autocomplete="email" required maxlength="254" />':''}
 ${!profile&&!reset?`<label for="password">Hasło${register||change?' (minimum 12 znaków)':''}</label><input id="password" name="password" type="password" autocomplete="${register||change?'new-password':'current-password'}" required minlength="${register||change?12:1}" maxlength="128" />`:''}
 <button class="primary-btn" type="submit">${profile?'Zapisz imię':reset?'Wyślij link':change?'Zapisz nowe hasło':register?'Utwórz konto':'Zaloguj się'}</button></form>
 ${profile?'<button class="ghost-btn" id="backCourse">Wróć do nauki</button><button class="ghost-btn" id="logout">Wyloguj się</button><button class="ghost-btn" id="passwordReset">Zmień hasło przez e-mail</button><hr><h2>Przenieś stare postępy</h2><p>W starej aplikacji kliknij „Eksportuj postępy”, a tutaj wybierz pobrany plik JSON. Import zastąpi postępy na tym koncie po potwierdzeniu.</p><label for="importFile">Plik z postępami</label><input id="importFile" type="file" accept="application/json,.json"><button class="ghost-btn" id="downloadAccount">Pobierz kopię danych</button>':!change?`<button class="ghost-btn" data-auth="${register||reset?'login':'register'}">${register||reset?'Mam konto — zaloguj się':'Utwórz konto'}</button>${!reset?'<button class="ghost-btn" data-auth="reset">Nie pamiętam hasła</button>':''}`:'<button class="ghost-btn" id="logout">Wyloguj się</button>'}`}
 <p id="accountMessage" class="message" role="status">${h(note)}</p><small>Hasła obsługuje Supabase Auth. Aplikacja nie zapisuje haseł lokalnie.</small>`;
 account.querySelector('input')?.focus();
}
function banner(text){
 let b=$('syncBanner');if(!b){b=document.createElement('div');b.id='syncBanner';b.className='sync-banner';b.setAttribute('role','alert');document.body.append(b);}
 b.innerHTML=`<div>${h(text)}</div><button class="ghost-btn" id="retrySync">${conflict?'Wczytaj zapis z chmury':'Ponów zapis'}</button><button class="ghost-btn" id="backupUnsaved">Pobierz kopię moich zmian</button>`;
}
async function cloudSave(){
 if(!user||!ready||conflict)return;
 const current=JSON.stringify(snapshot());if(current===lastSnapshot&&!dirty)return;
 dirty=true;status('Zapisywanie…');if(saving)return;
 saving=true;const epoch=generation,owner=user.id,body=JSON.parse(current);
 try{
 const {data,error}=await client.rpc('save_learning_state',{expected_revision:revision,new_payload:body});
 if(epoch!==generation||owner!==user?.id)return;
 if(error)throw error;
 revision=Number(data);lastSnapshot=current;dirty=JSON.stringify(snapshot())!==current;status(dirty?'Zapisywanie…':'✓ Zapisano na Twoim koncie');$('syncBanner')?.remove();
 }catch(e){if(epoch!==generation)return;dirty=true;conflict=e.code==='40001';status(conflict?'Zmiany na innym urządzeniu':'Nie zapisano — sprawdź połączenie');banner(conflict?'Na innym urządzeniu zapisano nowsze postępy. Pobierz kopię swoich zmian przed wczytaniem chmury.':'Zmiany czekają w tej karcie. Pozostaw ją otwartą i ponów zapis po odzyskaniu połączenia.');}
 finally{if(epoch===generation){saving=false;if(dirty&&!conflict&&lastSnapshot===current)queueMicrotask(cloudSave);}}
}
async function loadCloud(){
 if(!user)return;const epoch=generation,id=user.id;
 const {data,error}=await client.from('learning_state').select('payload,revision').eq('user_id',id).maybeSingle();
 if(epoch!==generation||id!==user?.id)return;
 if(error)throw error;
 view='home';restore(data?.payload||{});revision=Number(data?.revision||0);lastSnapshot=JSON.stringify(snapshot());dirty=false;conflict=false;ready=true;render();status('✓ Zsynchronizowano z kontem');$('syncBanner')?.remove();
}
function clearAccount(){studentPortal?.clear();generation++;ready=false;user=null;dirty=false;saving=false;conflict=false;revision=0;view='home';restore();lastSnapshot='';$('content').replaceChildren();$('syncBanner')?.remove();window.speechSynthesis?.cancel();}
async function authChange(event,session){
 if(event==='PASSWORD_RECOVERY'){recovering=true;user=session?.user;showAccount('change');return;}
 if(!session){recovering=false;clearAccount();showAccount();return;}
 if(user?.id===session.user.id&&ready){user=session.user;return;}
 clearAccount();user=session.user;
 if(recovering){showAccount('change');return;}
 showAccount('login','Wczytuję Twoje postępy…');
 try{await loadCloud();if(user&&ready){account.hidden=true;app.hidden=!!studentPortal;if(studentPortal)await studentPortal.login(user);}}catch{showAccount('login','Nie udało się pobrać postępów. Sprawdź połączenie i konfigurację bazy, następnie odśwież stronę.');}
}
async function submitAccount(e){
 e.preventDefault();const form=e.target,button=form.querySelector('button');button.disabled=true;message('Chwileczkę…');
 const fd=new FormData(form),email=String(fd.get('email')||''),password=String(fd.get('password')||'');
 try{
 let result;
 if(authMode==='login')result=await client.auth.signInWithPassword({email,password});
 if(authMode==='register')result=await client.auth.signUp({email,password,options:{data:{display_name:String(fd.get('name')||'')},emailRedirectTo:location.origin}});
 if(authMode==='reset')result=await client.auth.resetPasswordForEmail(email,{redirectTo:location.origin+'/?recovery=1'});
 if(authMode==='profile')result=await client.auth.updateUser({data:{display_name:String(fd.get('name')||'')}});
 if(authMode==='change')result=await client.auth.updateUser({password});
 if(result?.error)throw result.error;
 if(authMode==='register')message('Sprawdź pocztę — jeśli rejestracja wymaga potwierdzenia, znajdziesz tam link aktywacyjny.');
 if(authMode==='reset')message('Jeśli konto istnieje, otrzymasz wiadomość z linkiem. Sprawdź też spam.');
 if(authMode==='profile')message('Imię zapisane.');
 if(authMode==='change'){recovering=false;history.replaceState({},'',location.pathname);await client.auth.signOut();showAccount('login','Hasło zmienione. Zaloguj się ponownie.');}
 }catch(e){message(e.status===429?'Zbyt wiele prób. Poczekaj chwilę.':'Nie udało się wykonać operacji. Sprawdź dane, potwierdzenie adresu e-mail i połączenie.');}
 finally{form.querySelector('[name=password]')&&(form.querySelector('[name=password]').value='');button.disabled=false;}
}
function downloadSnapshot(){const blob=new Blob([JSON.stringify({app:'Cyber od zera',version:2,state:snapshot()},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='cyber-kopia-konta.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
document.addEventListener('submit',e=>{if(e.target.id==='accountForm')submitAccount(e);});
document.addEventListener('click',async e=>{
 const t=e.target.closest('button');if(!t)return;
 if(t.dataset.auth){showAccount(t.dataset.auth);return;}
 if(t.id==='previewCourse'){account.hidden=true;app.hidden=false;render();status('Podgląd — postępy nie są zapisywane');return;}
 if(t.id==='profileButton'){showAccount(configured?'profile':'login');return;}
 if(t.id==='backCourse'){account.hidden=true;app.hidden=!!studentPortal;studentPortal?.show();return;}
 if(t.id==='studentHome'){await cloudSave();if(dirty)return;app.hidden=true;studentPortal?.show();return;}
 if(t.id==='logout'){
  await cloudSave();if(dirty&&!confirm('Masz niezapisane zmiany. Wylogować się i je odrzucić?'))return;
  const {error}=await client.auth.signOut();if(error){message('Nie udało się wylogować. Spróbuj ponownie.');return;}
  clearAccount();showAccount();return;
 }
 if(t.id==='passwordReset'){const {error}=await client.auth.resetPasswordForEmail(user.email,{redirectTo:location.origin+'/?recovery=1'});message(error?'Nie udało się wysłać wiadomości.':'Wysłano link zmiany hasła.');return;}
 if(t.id==='downloadAccount'||t.id==='backupUnsaved'){downloadSnapshot();return;}
 if(t.id==='retrySync'){
  if(conflict){if(!confirm('Wczytać chmurę i odrzucić niezapisane zmiany z tej karty? Najpierw możesz pobrać kopię.'))return;try{await loadCloud();}catch{banner('Nie udało się pobrać zapisu. Spróbuj ponownie.');}}
  else await cloudSave();return;
 }
 if(e.composedPath().includes(app)){
  if(t.id==='examNext'&&view==='exam-done'){examHistory.push({at:new Date().toISOString(),score:window.latestScore,questions:snapshot().exam.questions,answers:structuredClone(examAnswers)});examHistory=examHistory.slice(-100);}
  queueMicrotask(cloudSave);
 }
});
document.addEventListener('change',async e=>{
 if(e.target.id!=='importFile'||!user||!ready)return;
 const file=e.target.files[0];if(!file)return;
 try{
 if(file.size>524288)throw Error('Plik jest za duży (maksymalnie 512 KB).');
 const data=JSON.parse(await file.text());if(data.app!=='Cyber od zera')throw Error('To nie jest eksport Cyber od zera.');
 const progress=normalizeProgress(data.state?.progress||data.progress,LESSONS,GLOSSARY);
 if(!confirm(`Zastąpić postępy konta ${user.email}? Import zawiera ${progress.done.length} ukończonych lekcji.`))return;
 view='home';restore(data.state?{...data.state,progress}:{progress});render();await cloudSave();message(dirty?'Import czeka na zapis. Sprawdź komunikat synchronizacji.':'Postępy przeniesione.');
 }catch(err){message(err.message);}finally{e.target.value='';}
});
// Capture keyboard-driven review too. Save complete answers, not only score totals.
document.addEventListener('keydown',()=>queueMicrotask(cloudSave));
window.addEventListener('beforeunload',e=>{if(dirty||saving){e.preventDefault();e.returnValue='';}});
window.addEventListener('online',()=>cloudSave());
async function syncClean(){
 if(!user||!ready||saving||dirty||conflict||!account.hidden||document.hidden)return;
 const epoch=generation,before=JSON.stringify(snapshot());
 const {data,error}=await client.from('learning_state').select('payload,revision').eq('user_id',user.id).maybeSingle();
 if(error||epoch!==generation||dirty||saving||JSON.stringify(snapshot())!==before)return;
 if(data&&Number(data.revision)!==revision){view='home';restore(data.payload);revision=Number(data.revision);lastSnapshot=JSON.stringify(snapshot());render();status('✓ Pobrano zmiany z drugiego urządzenia');}
}
window.addEventListener('focus',()=>syncClean());setInterval(()=>syncClean(),15000);
showAccount();
if(client){
 recovering=new URLSearchParams(location.search).get('recovery')==='1';
 client.auth.onAuthStateChange((event,session)=>{setTimeout(()=>authChange(event,session),0);});
}
